functions._matchesAgreementType:
function _matchesAgreementType(templateType, docType) {
  if (!templateType || !docType) return false;
  var a = templateType.toLowerCase().trim();
  var b = docType.toLowerCase().trim();
  if (a === b) return true;
  if (a.indexOf(b) !== -1 || b.indexOf(a) !== -1) return true;
  var catalog = typeof getAgreementTypeMatcher === "function" ? getAgreementTypeMatcher() : [];
  function getAliasGroup(val) {
    for (var i = 0; i < catalog.length; i++) {
      var cat = catalog[i];
      if (cat.label.toLowerCase() === val) return cat.aliases.concat([cat.label.toLowerCase()]);
      for (var j = 0; j < cat.aliases.length; j++) {
        if (val.indexOf(cat.aliases[j]) !== -1 || cat.aliases[j].indexOf(val) !== -1) {
          return cat.aliases.concat([cat.label.toLowerCase()]);
        }
      }
    }
    return null;
  }
  var groupA = getAliasGroup(a);
  var groupB = getAliasGroup(b);
  if (groupA && groupB && groupA.length === groupB.length && groupA[0] === groupB[0]) return true;
  if (groupA) {
    for (var k = 0; k < groupA.length; k++) {
      if (b.indexOf(groupA[k]) !== -1 || groupA[k].indexOf(b) !== -1) return true;
    }
  }
  if (groupB) {
    for (var k = 0; k < groupB.length; k++) {
      if (a.indexOf(groupB[k]) !== -1 || groupB[k].indexOf(a) !== -1) return true;
    }
  }
  return false;
}

