    // 2026-05-24: route each pick through compare's STANDALONE runner
    // instead of runDeal360Analysis. Compare Doc is no longer bundled
    // with Legal Risks — that combined experience lives in Legal Review.
    // Helper that dispatches into compare.runStandalone with a normalized
    // payload + mode. Falls back to the direct function if dispatch isn't
    // wired (defensive — bundle eval order shouldn't make this miss).
    function _runCompareStandalone(payload, runMode) {
      if (window.eli && window.eli.dispatch) {
        var r = window.eli.dispatch("compare", "runStandalone", payload, runMode);
        if (r !== undefined) return;
      }
      if (typeof window._runStandalone === "function") {
        window._runStandalone(payload, runMode);
      } else if (typeof showToast === "function") {
        showToast("⚠️ Compare runner not loaded. Re-open the tool.", "err");
      }
    }
    if (mode === "template") {
      var selEl = document.getElementById("cmpTemplateSel");
      if (!selEl || selEl.style.display === "none") {
        showToast("⚠️ No templates available. Upload a file instead.");
        return;
      }
      var tmpl = window._cmpTemplates[parseInt(selEl.value, 10)];
      if (!tmpl) {
        showToast("⚠️ Select a template.");
        return;
      }
      _runCompareStandalone({ template: tmpl }, "template");
    } else if (mode === "upload") {
      var fileInp = document.getElementById("cmpFileInput");
      if (!fileInp || !fileInp.files[0]) {
        showToast("⚠️ Select a file to compare against.");
        return;
      }
      var btn = document.getElementById("cmpLaunchBtn");
      btn.innerText = "⏳ Reading file...";
      btn.style.opacity = "0.6";
      btn.style.pointerEvents = "none";
      handleFileSelect(fileInp.files[0], function (text) {
        _runCompareStandalone({ text: typeof text === "string" ? text : "", mode: "new" }, "new");
      });
    } else if (mode === "version") {
      var vRadio = document.querySelector('input[name="cmp_version"]:checked');
      if (!vRadio || !versions || versions.length === 0) {
        showToast("⚠️ No past version selected.");
        return;
      }
      var ver = versions[parseInt(vRadio.value, 10)];
      _runCompareStandalone({ version: ver }, "version");
    }
  };
}

functions.renderCompareResults:
function renderCompareResults(rawData, mode, appendMode) {
  // Stats — fires trophies tied to documentsCompared (t131, t158, t161, t184).
  // Guard against double-counting when the same data re-renders by stashing
  // a flag on the data itself; subsequent re-renders skip the record.
  if (rawData && !rawData._eliCompareCounted) {
    try {
      Object.defineProperty(rawData, "_eliCompareCounted", { value: true, enumerable: false });
      if (window.eli && window.eli.stats && typeof window.eli.stats.record === "function") {
        window.eli.stats.record("documentsCompared");
        window.eli.stats.record("docsReviewed");
      }
    } catch (_) {}
  }
  var summaryBullets = [];
  var overallAssessment = "";
  var items = rawData;
  var aiScore = null;
  var aiSimText = null;

  if (!Array.isArray(rawData)) {
    if (rawData.critical_summary) {
      summaryBullets = Array.isArray(rawData.critical_summary) ? rawData.critical_summary : [rawData.critical_summary];
    }
    overallAssessment = rawData.overall_assessment || "";
    items = rawData.changes || [];
    aiScore = parseInt(rawData.similarity_score, 10);
    if (isNaN(aiScore)) aiScore = null;
    aiSimText = rawData.similarity_text;
  }
  window.ELI_COMPARE_STATE = items;
  window.ELI_COMPARE_STATE.forEach(function (x) {
    x.actionStatus = "PENDING";
    x.rationale = "";
    x.originalIdx = window.ELI_COMPARE_STATE.indexOf(x);
  });
  var out;
  var targetContainer;
  if (typeof appendMode === "string") {
    out = document.getElementById("output");
    var el = document.getElementById(appendMode);
    targetContainer = el || out;
  } else if (!appendMode) {
    out = window.eli.ui.claimOutput();
    targetContainer = out;
  } else {
    out = document.getElementById("output");
    targetContainer = out;
  }
  out.classList.add("eli-view-enter");
  // #output is a flex column (kernel .output-area). A full-takeover tool
  // must keep its content top-aligned — otherwise collapsing the master
  // header shrinks the content and it drifts to the bottom of the
  // viewport. Only assert this for the standalone (claimOutput) path.
  if (!appendMode && out && out.style) {
    out.style.justifyContent = "flex-start";
    out.style.alignItems = "stretch";
  }
  var isVersion = mode === "version" || mode === "old";
  // banner removed
  var sumBox = null;

  var dbHeader = document.getElementById("lrlDashboardHeaderTitle");
  if (dbHeader) {
    dbHeader.innerText = "📊 COMPARISON & LEGAL RISKS";

    if (!document.getElementById("lrlComboInstruction")) {
      var instructionDiv = document.createElement("div");
      instructionDiv.id = "lrlComboInstruction";
      instructionDiv.style.cssText = "font-size:10.5px; font-weight:800; text-align:center; color:#64748b; letter-spacing:0.5px; text-transform:uppercase; margin-bottom:12px; margin-top:-3px; padding:0 14px;";
      instructionDiv.innerHTML = "Review template deviations below, then scroll down to see the legal risk analysis.";

      var compareTarget = document.getElementById("lrlCompareTarget");
      if (compareTarget && compareTarget.parentNode) {
        compareTarget.parentNode.insertBefore(instructionDiv, compareTarget);
      }
    }
  }

  if (summaryBullets.length > 0 || overallAssessment || items.length >= 0) {
    sumBox = document.createElement("div");
    sumBox.style.cssText = "margin-bottom:15px;";

    var pragmaticScore = aiScore !== null ? aiScore : Math.max(15, Math.round(100 - items.length * 10));
    if (items.length === 0) pragmaticScore = 100;

    var simText =
      aiSimText || overallAssessment || "The document is heavily modified with major structural or clause deviations.";
    if (!aiSimText && !overallAssessment) {
      if (pragmaticScore >= 90)
        simText = "The document is nearly identical to the template with minimal substantive changes.";
      else if (pragmaticScore >= 70)
        simText = "The document is highly similar to the template, containing only a few targeted deviations.";
      else if (pragmaticScore >= 50)
        simText = "The document shares a foundation with the template but contains moderate substantive deviations.";
    }

    var bHtml = `
      <div style="background:#fff; border:1px solid #dce3ec; border-left:3px solid #1d4ed8; padding:14px;">
          <div style="display:flex; justify-content:space-between; align-items:flex-end; margin-bottom:10px;">
              <div style="font-size:12px; font-weight:800; color:#1d4ed8; text-transform:uppercase;">
                  KEY DIFFERENCES OVERVIEW
              </div>
              <div style="font-size:18px; font-weight:900; color:${pragmaticScore >= 75 ? "#22c55e" : pragmaticScore >= 50 ? "#f59e0b" : "#ef4444"};">
                  ${pragmaticScore}% <span style="font-size:9px; font-weight:700; color:#64748b; letter-spacing:0.5px; vertical-align:middle;">ALIGNED</span>
              </div>
          </div>
          <div style="font-size:13px; font-weight:600; color:#0f172a; margin-bottom:12px; padding-bottom:10px; border-bottom:1px solid #e2e8f0;">
              ${simText}
          </div>
    `;
    if (summaryBullets.length > 0) {
      bHtml += "<ul style='margin:0 0 10px 0;padding-left:18px;font-size:12px;color:#37474f;line-height:1.55;'>";
      summaryBullets.forEach(function (b) {
        bHtml += "<li style='margin-bottom:5px;'>" + b + "</li>";
      });
      bHtml += "</ul>";
    }
    bHtml += "</div>";
    sumBox.innerHTML = bHtml;
  }
  if (!items || items.length === 0) {
    if (sumBox) targetContainer.appendChild(sumBox);
    var noChanges = document.createElement("div");
    noChanges.className = "placeholder";
    noChanges.textContent = "No substantive differences found.";
    targetContainer.appendChild(noChanges);
    return;
  }
  var missingItems = [];
  var deviationItems = [];
  var additionItems = [];
  items.forEach(function (item, idx) {
    item._globalIdx = idx;
    if (item.new_snippet === "[DELETED]") missingItems.push(item);
    else if (item.original_snippet === "[NEWLY ADDED]") additionItems.push(item);
    else deviationItems.push(item);
  });
  // showBadges read — v2 used a top-level `userSettings` global that v3
  // doesn't have. Read the same key v2 wrote (`eli_user_settings` in
  // localStorage; kept as-is per backwards-compat) through eli.compat.
  var showBadges = (function () {
    try {
      var raw = window.eli && window.eli.compat && window.eli.compat.lsGet
        ? window.eli.compat.lsGet("eli_user_settings")
        : null;
      var s = raw ? JSON.parse(raw) : null;
      return !!(s && s.showCompareRisk === true);
    } catch (e) { return false; }
  })();
  var is3rdParty = window._poMode === "3rd party";
  var zones = [
    {
      id: "missing",
      title: "Missing Protections",
      subtitle: is3rdParty
        ? "Clauses in your template that the draft omits entirely"
        : "Clauses removed from the prior version",
      items: missingItems,
      icon: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><line x1="8" y1="12" x2="16" y2="12"/></svg>',
      headerBg: "linear-gradient(135deg,#991b1b,#dc2626)",
      borderColor: "#dc2626",
      cardBorder: "#fca5a5",
      snippetLabel: is3rdParty ? "TEMPLATE CLAUSE (NOT INCLUDED)" : "LANGUAGE FROM PRIOR VERSION (DELETED)",
      snippetBg: "#fff5f5",
      snippetBorder: "#ffcdd2",
      snippetLabelColor: "#b71c1c",
    },
    {
      id: "deviations",
      title: "Deviations",
      subtitle: is3rdParty
        ? "Clauses that exist in both but differ materially \u2014 your standard vs. their draft"
        : "Clauses modified between versions",
      items: deviationItems,
      icon: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',
      headerBg: "linear-gradient(135deg,#5b21b6,#7c3aed)",
      borderColor: "#7c3aed",
      cardBorder: "#c4b5fd",
      snippetLabel: is3rdParty ? "DEVIATES FROM TEMPLATE" : "MODIFIED FROM PRIOR VERSION",
      snippetBg: "#faf5ff",
      snippetBorder: "#d8b4fe",
