          zone.title +
          "]</span>" +
          "</strong>" +
          "</div>" +
          '<div style="display:flex; gap:6px; align-items:center;">' +
          (showBadges
            ? '<span class="badge" style="background:' +
            color +
            "15; color:" +
            color +
            "; font-size:9px; font-weight:800; padding:2px 6px; border-radius:2px; border:1px solid " +
            color +
