            (item.change_type || "MODERATE").toUpperCase() +
            "</span>"
            : "") +
          "</div></div>" +
          '<div style="font-size:12px; color:#546e7a; margin-bottom:12px; line-height:1.4;">' +
          (item.description || "Omission of text")
