  };
  btnHome.onclick = showHome;
  if (typeof appendMode !== "string") {
    targetContainer.appendChild(btnHome);
  }
}

functions._compareParseJson:
function _compareParseJson(jsonString) {
  if (!jsonString) return {};
  var clean = String(jsonString)
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .replace(/^[^{[]*/, "")
    .replace(/[^}\]]*$/, "")
    .trim();
  try { return JSON.parse(clean); }
  catch (e) {
    try {
      var recovered = [];
      var rx = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g, m;
      while ((m = rx.exec(clean)) !== null) {
        try { recovered.push(JSON.parse(m[0])); } catch (e2) { /* skip */ }
      }
      if (recovered.length > 0) return recovered;
    } catch (e3) { /* fall through */ }
    try {
      var fixed = clean.replace(/(?<!["}])\n/g, "\\n");
      if (fixed.match(/^\[\w+\]/)) throw new Error("plain text list");
      return JSON.parse(fixed);
    } catch (e4) {
      // 2026-05-13 audit fix: removed the fake-findings fallback that
      // fabricated `{summary, changes:[{clause:"General", impact:"Review Manually"}]}`
      // when JSON parse failed. That was a "fallback to fix a bug" anti-pattern
      // (CLAUDE.md): it disguised real AI-output failures as low-quality results
      // the user couldn't tell from a true comparison. Now we return an empty
      // shape and let the caller surface the parse failure honestly.
      if (clean.charAt(0) === "[") return [];
      return {};
    }
  }
}

functions.runVersionCompare:
function runVersionCompare(historicalVersion) {
  // Cancel token + tool-owned overlay (2026-05-16). The smile loader is
  // rendered by compare itself (see _cmpShowSmile in init.js) — kernel
  // setLoading suppresses its overlay when a tool overlay is up, so
  // the Cancel button HAS to live inside the tool's own overlay HTML.
  var _cmpToken = (window.eli && window.eli.cancel && typeof window.eli.cancel.token === "function")
    ? window.eli.cancel.token() : null;
  function _cmpOnCancel() {
    if (_cmpToken && typeof _cmpToken.abort === "function") {
      _cmpToken.abort("user_cancel");
    }
    if (typeof window._cmpHideSmile === "function") {
      try { window._cmpHideSmile(); } catch (_) {}
    }
    try { setLoading(!1); } catch (_) {}
    // 2026-05-16: call showCancelledState so the FSM parks at
    // "cancelled" long enough (~1.2s) for eli_kit's cancelled-screen
    // subscriber to fire. Without this, setLoading(false) bounces
    // through scanning→cancelled→idle in microseconds and the
    // dialog's 120ms gate skips it.
    if (typeof showCancelledState === "function") {
      try { showCancelledState(); } catch (_) {}
    } else if (typeof showToast === "function") {
      showToast("Compare cancelled.", "info");
    }
  }
  setLoading(!0, "redline");
  if (typeof window._cmpPaintSmileLoader === "function") {
    try { window._cmpPaintSmileLoader(_cmpOnCancel); } catch (_) {}
  }
  Word.run(async (context) => {
    let body = context.document.body;
    let html = body.getHtml();
    let ooxml = body.getOoxml();
    await context.sync();
    return { html: html.value, ooxml: ooxml.value };
  })
    .then((current) => {
      let currentHtml = current.html || "";
      let currentOoxml = current.ooxml || "";
      // 2026-05-13 audit fix: v2 global `getCleanTextAndContext` is not
      // defined in v3 — replaced by the provider helper. Returns a plain
      // string (not {text}), so the .text indirection is gone too.
      let currentText = window.eli.host.helpers.cleanText(currentHtml);
      let oldText = window.eli.host.helpers.cleanText(historicalVersion.html || "");
      let histLabel = historicalVersion.displayNumber
        ? "Version #" + historicalVersion.displayNumber
        : "Historical Snapshot";
      let currentLabel = "Current Active Document";
      // Strip noise from current OOXML so the diff isn't drowned in rsids/dates.
      if (currentOoxml && typeof _tpStripOoxmlNoise === "function") {
        currentOoxml = _tpStripOoxmlNoise(currentOoxml);
      }
      // Redline-aware diff via OOXML — captures accept/reject decisions that pure
      // text comparison can't see. Falls back gracefully when either snapshot
      // pre-dates the bodyOoxml capture (older snapshots have only `html`).
      let transitionsBlock = "";
      let rawCompareResult = null; // raw output from compareSnapshotsRedlineAware;
                                   // used downstream to detect unmarked changes
                                   // (paragraphs edited with track-changes off).
      // 2026-05-17: diagnostic — log whether OOXML is present on both
      // sides AND the compare result counts. This surfaces "compare
      // looks broken" cases: if historical lacks bodyOoxml the
      // redline-aware diff is skipped entirely and we fall back to
      // text-only (which can't see accept/reject decisions).
      if (window.eli && window.eli.log && typeof window.eli.log.event === "function") {
        window.eli.log.event("compare", "version_compare_inputs", {
          historicalHasOoxml: !!historicalVersion.bodyOoxml,
          historicalOoxmlLen: (historicalVersion.bodyOoxml || "").length,
          currentHasOoxml: !!currentOoxml,
          currentOoxmlLen: (currentOoxml || "").length,
          historicalLabel: historicalVersion.label || "",
        });
      }
      if (
        historicalVersion.bodyOoxml &&
        currentOoxml &&
        typeof window.compareSnapshotsRedlineAware === "function"
      ) {
        try {
          let result = window.compareSnapshotsRedlineAware(
            { bodyOoxml: historicalVersion.bodyOoxml },
            { bodyOoxml: currentOoxml },
          );
          rawCompareResult = result;
          if (window.eli && window.eli.log && typeof window.eli.log.event === "function") {
            window.eli.log.event("compare", "version_compare_result", {
              hasTransitions: !!(result && Array.isArray(result.transitions)),
              transitionCount: (result && Array.isArray(result.transitions)) ? result.transitions.length : 0,
              summary: (result && result.summary) || null,
              error: (result && result.error) || null,
            });
          }
          if (result && Array.isArray(result.transitions)) {
            // 2026-05-17 v2: OUTCOME-FIRST labels. Previous attempt used
            // "ACCEPTED DELETION" / "REJECTED DELETION" tags + a semantic
            // glossary, but the AI consistently inverted those when
            // writing prose ("rejected deletion of X" for an accepted-
            // deletion). Root cause: "accepted/rejected" + "deletion" is
            // a double-noun the model mangles. Fix: lead each line with
            // the plain outcome (REMOVED / KEPT / ADDED / NOT ADDED) so
            // the AI's prose follows directly from the outcome word, no
            // semantic re-derivation needed.
            let typeToOutcome = {
              "accepted-insertion": { tag: "ADDED",     verb: "added" },
              "rejected-insertion": { tag: "NOT ADDED", verb: "not added" },
              "accepted-deletion":  { tag: "REMOVED",   verb: "removed" },
              "rejected-deletion":  { tag: "KEPT",      verb: "kept" },
              "new-insertion":      { tag: "NEW INSERTION (introduced after snapshot)",  verb: "introduced" },
              "new-deletion":       { tag: "NEW DELETION (introduced after snapshot)",   verb: "introduced" },
              "unmarked-change":    { tag: "UNMARKED EDIT (no track-changes wrapper)",  verb: "flagged" },
            };
            let stateChanges = result.transitions.filter(function (t) {
              return typeToOutcome.hasOwnProperty(t.type);
            });
            // Document-order sort (paragraph index ASC) so findings come
            // out Article 1 → 2 → 3 not Article 1 → 5 → 5 → 1.
            stateChanges.sort(function (a, b) {
              return (a.paragraphIdx || 0) - (b.paragraphIdx || 0);
            });
            let s = result.summary || {};
            if (stateChanges.length === 0) {
              transitionsBlock =
                "DECISION LOG: NO STATE CHANGES BETWEEN VERSIONS.\n" +
                "Both versions contain the same set of pending redlines (" + (s.retained || 0) + " retained). " +
                "No insertions or deletions were accepted, rejected, or newly introduced between the two snapshots. " +
                "Report this as no changes.\n\n";
            } else {
              // Per-transition line. Structure:
              //   "- ¶<idx> | <OUTCOME>: counterparty wanted to <verb> "<text>"; reviewer <agreed|reverted>."
              // The OUTCOME tag tells the AI exactly what happened to the
              // text. No double-noun "ACCEPTED DELETION" for the AI to
              // mis-invert.
              let evidence = stateChanges.slice(0, 200).map(function (t) {
                let txt = String(t.text || "").replace(/\s+/g, " ").trim();
                if (txt.length > 240) txt = txt.slice(0, 240) + "…";
                let by = t.author ? " · author: " + t.author : "";
                let outcome = typeToOutcome[t.type];
                let intent = "", decision = "";
                if (t.type === "accepted-insertion") {
                  intent = "counterparty proposed to ADD";
                  decision = "reviewer AGREED → text IS in the current doc";
                } else if (t.type === "rejected-insertion") {
                  intent = "counterparty proposed to ADD";
                  decision = "reviewer REVERTED → text is NOT in the current doc";
                } else if (t.type === "accepted-deletion") {
                  intent = "counterparty proposed to DELETE";
                  decision = "reviewer AGREED → text is NOT in the current doc";
                } else if (t.type === "rejected-deletion") {
                  intent = "counterparty proposed to DELETE";
                  decision = "reviewer REVERTED → text IS in the current doc";
                } else if (t.type === "new-insertion") {
                  intent = "reviewer introduced a NEW insertion";
                  decision = "now pending on top of the prior round";
                } else if (t.type === "new-deletion") {
                  intent = "reviewer introduced a NEW deletion";
                  decision = "now pending on top of the prior round";
                } else { // unmarked-change
                  intent = "counterparty edited text WITHOUT track changes";
                  decision = "possible hidden redline — flag for review";
                }
                // Fragmentation flag: if the text contains the " … "
                // joiner the classifier emits when multiple OOXML
                // segments are merged, mark it. The AI uses this to
                // know NOT to quote the text as a coherent sentence
                // (because it isn't — Word fragmented one edit into
                // N segments, and we glued the inserted/deleted
                // fragments together without the plain text between
                // them).
                var fragNote = (t._fragmentCount && t._fragmentCount > 1)
                  ? " · FRAGMENTED across " + t._fragmentCount + " segments — DO NOT quote verbatim; describe as a paragraph-level rewrite/edit"
                  : "";
                return "- ¶" + t.paragraphIdx + " | " + outcome.tag + ": " +
                       intent + " \"" + txt + "\"; " + decision + "." + by + fragNote;
              }).join("\n");
              transitionsBlock =
                "DECISION LOG (extracted from each version's OOXML — AUTHORITATIVE; document order):\n" +
                "Tally: " + (s.accepted || 0) + " counterparty edits agreed-with, " +
                  (s.rejected || 0) + " reverted, " +
                  (s.newRedlines || 0) + " new redlines introduced, " +
                  (s.unmarked || 0) + " unmarked (hidden) edits, " +
                  (s.retained || 0) + " still pending (NOT a change — informational only).\n\n" +
                "Each line below states the OUTCOME first. Take it literally:\n" +
                "  • REMOVED   = the text is GONE from the current doc.\n" +
                "  • KEPT      = the text is STILL IN the current doc (counterparty's proposed deletion was reverted).\n" +
                "  • ADDED     = the text IS in the current doc (counterparty's proposed insertion was kept).\n" +
                "  • NOT ADDED = the text is NOT in the current doc (counterparty's proposed insertion was reverted).\n\n" +
                evidence + "\n\n" +
                "IMPORTANT:\n" +
                "  1. Still-pending redlines are NOT in the log above — do not invent findings for them.\n" +
                "  2. Report ONLY decisions from the log. Do not pull additional findings from the cleaned-text comparison.\n" +
                "  3. The log is in document order. Your output's 'changes' array MUST follow that order (Article/Section 1 → 2 → 3 …). If multiple decisions hit the same clause, GROUP them into one finding for that clause, then move on. Never go back to an earlier clause after emitting a later one.\n" +
                "  4. Use the OUTCOME tag (REMOVED / KEPT / ADDED / NOT ADDED) to write your prose. e.g. a REMOVED line becomes \"Removed 'X' from §3\" — NEVER \"Rejected deletion of X.\" Stay in the active voice of what's in the doc now.\n\n" +
                ((s.unmarked || 0) > 0
                  ? "⚠️ CRITICAL: " + s.unmarked + " UNMARKED EDIT(S) detected. These are text edits the counterparty made without enabling Track Changes — they appear as identical differences in BOTH the accepted-view and rejected-view of the document. Treat each one as HIGH RISK, label it 'Unmarked edit' or 'Possible hidden redline', and recommend the reviewer manually verify the substantive impact.\n\n"
                  : "");
            }
          }
        } catch (_e) { /* fall through to text-only diff */ }
      }
      // 2026-05-17 v2: outcome-first prompt. Each finding leads with
      // what HAPPENED to the text in the doc (Removed / Kept / Added /
      // Not added) — never "Accepted/Rejected the deletion of X" which
      // the AI consistently inverts.
      let prompt = `
      You are a Senior Legal Editor writing a report on what changed between two snapshots of a contract. ${histLabel} had pending counterparty redlines; ${currentLabel} reflects the reviewer's decisions on them.

      ${transitionsBlock
          ? "PRIMARY EVIDENCE — the authoritative outcome log. Each line states what HAPPENED to the text. Group related decisions into clause-level findings:\n\n" + transitionsBlock
          : ""}

      INPUT TEXT FOR "${histLabel}" (the version with the third-party's pending redlines):
      """${oldText.substring(0, 500000)}"""

      INPUT TEXT FOR "${currentLabel}" (the version after the decisions):
      """${currentText.substring(0, 500000)}"""

      CRITICAL ANALYSIS RULES:
      1. LEAD WITH THE REVIEWER'S DECISION (Accepted / Rejected / Kept). Bind the verb to the SUBSTANCE of the change — never to the words "insertion" or "deletion" (that double-noun is where past versions got reversed). Map by OUTCOME tag in the log:
         • ADDED line     → "Accepted [substance of what was added]." (e.g. "Accepted a 30-day timeline for Colgate to confirm the confidential nature of oral disclosures.")
         • REMOVED line   → "Accepted removal of [substance of what was removed]." (e.g. "Accepted removal of the prior obligation for University to provide a written report on Research Project IP upon delivery.")
         • NOT ADDED line → "Rejected [substance of what was proposed]." (e.g. "Rejected the counterparty's proposed mutuality of indemnification.")
         • KEPT line      → "Kept [substance of what was kept]." or "Rejected removal of [substance]." (e.g. "Kept the original 30-day cure period.")
         • NEW INSERTION / NEW DELETION → "Introduced a new …" (this is the reviewer's NEW edit, not a decision on a prior round)
         • UNMARKED EDIT → "Flagged unmarked edit in §N — counterparty changed text without track changes."
         FORBIDDEN: "Accepted the deletion of X", "Rejected the insertion of X", "Accepted the insertion of X", "Rejected the deletion of X". The double-noun is where past prompts inverted. Use "Accepted removal of X" / "Accepted [substance]" / "Rejected [substance]" / "Kept [substance]" instead — the substance is concrete, the decision verb cannot be flipped.
      1a. FRAGMENTED log lines (marked "FRAGMENTED across N segments") are NOT a single coherent sentence — they're disjoint OOXML pieces glued with " … " separators. DO NOT quote them verbatim. Describe what HAPPENED at the paragraph level using the cleaned-text input. e.g. "Accepted a rewrite of §72 to require an acknowledgement statement in all Publications", "Accepted restructuring §5 to apply symmetrically to both parties".
      1b. ADDED + REMOVED in the SAME paragraph = ONE rewrite/replacement decision, not two. Use EXACTLY ONE decision verb at the START of the sentence (Accepted / Rejected / Kept / Introduced); describe the rewrite's content with a colon or em-dash, never with a second past-tense verb. FORBIDDEN: "Accepted a rewrite that adds X and removed Y" (reads as two actions). REQUIRED: "Accepted the counterparty's rewrite of the Confidential Information definition — adds a 30-day timeframe for confirming oral disclosures, drops references to specific disclosure recipients." Or: "Accepted a rewrite of §72: now requires acknowledgement in all Publications; the prior 'Colgate's permission' language is gone." The decision verb owns the whole sentence; the content uses present-tense / noun phrases / em-dash structure.
      2. NO PRONOUN. Never write "You", "We", or "The reviewer" — start with the bare past-tense verb (Removed / Kept / Added / Did not add / Introduced / Flagged).
      3. GROUP BY CLAUSE — ONE FINDING PER CLAUSE. Collect every decision that touched the same article/section into a SINGLE entry summarizing the cumulative effect on that clause. If five log lines all hit "Article 5 — Indemnity", that becomes ONE Indemnity finding.
      4. DOCUMENT ORDER. The 'changes' array MUST be sorted by paragraph index (the log is already pre-sorted). Article/Section 1 → 2 → 3 …; never go back to an earlier clause after emitting a later one.
      5. IMPACT IS RELATIVE TO COLGATE. "High Risk" = decision worsened Colgate's position (e.g., a counterparty-favorable deletion was accepted). "Better" = improved Colgate's position. "Neutral" = housekeeping / administrative.
      6. IGNORE MISSING NUMBERING and WHITESPACE — extraction artifacts, not real changes.
      7. ${transitionsBlock
          ? "Trust the DECISION LOG above as the authoritative source. If a log line says REMOVED, your finding describes a removal — do NOT second-guess it from the cleaned text."
          : "Compare the cleaned text for substantive changes between the versions."}

      OUTPUT FORMAT (STRICT JSON ONLY):
      {
        "summary": "2-3 sentence overview. Lead with a decision tally: 'Accepted N counterparty edits, rejected M, kept L (rejected the counterparty's deletions), introduced K new edits.' Then 1-2 sentences on the most consequential decisions and their net effect on Colgate's position. NO 'You' / 'We' / 'The reviewer'.",
        "changes": [
           {
             "clause": "Clause Name (e.g. Indemnity, Limitation of Liability)",
             "change": "Decision-first description. Start with 'Accepted …', 'Accepted removal of …', 'Rejected …', 'Kept …', 'Introduced …', or 'Flagged …'. Bind the verb to the SUBSTANCE — never to the words 'insertion'/'deletion'. Never write 'Accepted/Rejected the deletion/insertion of X' — that double-noun phrasing gets inverted. Use 'Accepted removal of X' or 'Accepted [substance]' instead.",
             "impact": "High Risk" | "Neutral" | "Better"
           }
        ]
      }
    `;
      // Stash the raw compare result globally so the in-app "🔍 Raw transitions"
      // debug button (rendered in renderVersionReport) can show the JSON without
      // needing devtools. Cleared on each new compare run.
      window._eliLastCompareResult = rawCompareResult;
      return window.eli.ai.complete(prompt, { signal: _cmpToken ? _cmpToken.signal : null }).then((result) => {
        let analysis = _compareParseJson(result);
        // Pass the transitions block + raw result through to renderVersionReport
        // so the Deep Dive button can leverage the same redline-aware evidence
        // and the debug button can display the raw JSON.
        renderVersionReport(analysis, historicalVersion.label, oldText, currentText, transitionsBlock, rawCompareResult);
      });
    })
    .catch(handleError)
    .finally(() => {
      setLoading(!1);
      if (typeof window._cmpHideSmile === "function") {
        try { window._cmpHideSmile(); } catch (_) {}
      }
    });
}

functions.renderVersionReport:
function renderVersionReport(data, verLabel, oldText, currentText, transitionsBlock, rawCompareResult) {
  if (!data) data = {};
  if (!data.summary) data.summary = "Analysis unavailable.";
  if (!Array.isArray(data.changes)) data.changes = [];
  let out = window.eli.ui.claimOutput();
  // Keep the report top-aligned in the flex-column #output (see
  // renderCompareResults for the rationale — collapsing a header
  // otherwise lets the content drift to the bottom of the viewport).
  if (out && out.style) {
    out.style.justifyContent = "flex-start";
    out.style.alignItems = "stretch";
  }
  let header = createConfigHeader(null, "🕒", "Version Report: " + verLabel, { marginBottom: "12px" });
  out.appendChild(header);
  // ⚠️ Unmarked-change warning card. Rendered ABOVE the executive summary so a
  // reviewer can't miss it — these are edits the counterparty made without
  // enabling Track Changes (possibly hiding redlines), detected by the dual-
  // diff in compareSnapshotsRedlineAware.
  let unmarkedChanges = rawCompareResult && Array.isArray(rawCompareResult.transitions)
    ? rawCompareResult.transitions.filter(function (t) { return t.type === "unmarked-change"; })
    : [];
  if (unmarkedChanges.length > 0) {
    let warn = document.createElement("div");
    warn.style.cssText = "border:2px solid #d97706; background:linear-gradient(135deg,#fef3c7,#fde68a); padding:14px 16px; margin-bottom:15px; border-left-width:6px;";
    let rowsHtml = unmarkedChanges.slice(0, 25).map(function (t) {
      let label = t.wholeParagraph ? "Whole paragraph added (no track changes)" : "Inline edit (no track changes)";
      let body = String(t.text || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      return '<tr style="border-bottom:1px solid #fcd34d;">' +
             '<td style="padding:7px 8px; font-weight:700; color:#92400e; vertical-align:top; white-space:nowrap;">¶' + (t.paragraphIdx + 1) + '</td>' +
             '<td style="padding:7px 8px; color:#78350f; vertical-align:top; font-weight:600;">' + label + '</td>' +
             '<td style="padding:7px 8px; color:#451a03; vertical-align:top; font-family:ui-monospace,Consolas,monospace; font-size:11px; line-height:1.45;">' + body + '</td>' +
             '</tr>';
    }).join("");
    let truncatedNote = unmarkedChanges.length > 25
      ? '<div style="margin-top:8px; font-size:11px; color:#92400e; font-style:italic;">…and ' + (unmarkedChanges.length - 25) + ' more.</div>'
      : '';
    warn.innerHTML =
      '<div style="display:flex; align-items:center; gap:10px; margin-bottom:8px;">' +
        '<div style="font-size:20px;">⚠️</div>' +
        '<div style="font-size:13px; font-weight:800; color:#7c2d12; text-transform:uppercase; letter-spacing:0.5px;">' +
          unmarkedChanges.length + ' Unmarked Change' + (unmarkedChanges.length > 1 ? 's' : '') + ' Detected (Possible Hidden Redlines)' +
        '</div>' +
      '</div>' +
      '<div style="font-size:12px; color:#78350f; margin-bottom:10px; line-height:1.5;">' +
        'These edits appear as identical differences in BOTH the accepted-view and rejected-view of the document, meaning they have NO track-changes wrapper. The counterparty may have edited text with Track Changes disabled. Manually verify each one before accepting the version.' +
      '</div>' +
      '<table style="width:100%; border-collapse:collapse; font-size:11px; background:rgba(255,255,255,0.55);">' +
        '<tr style="background:#fde68a; text-align:left; border-bottom:1px solid #d97706;">' +
          '<th style="padding:6px 8px; color:#7c2d12;">Para</th>' +
          '<th style="padding:6px 8px; color:#7c2d12;">Type</th>' +
          '<th style="padding:6px 8px; color:#7c2d12;">Edit</th>' +
        '</tr>' +
        rowsHtml +
      '</table>' + truncatedNote;
    out.appendChild(warn);
  }
  // Executive Summary — premium card. Navy gradient header with eyebrow +
  // title + change count chip; gold left rail; summary paragraph; striped
  // table with risk-pill impact column.
  let changes = Array.isArray(data.changes) ? data.changes : [];
  let _esEsc = function (s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };
  let _impactPill = function (impact) {
    let raw = String(impact || "").trim();
    let lower = raw.toLowerCase();
    let bg = "#ecfdf5", border = "#86efac", color = "#14532d";   // default: positive/neutral
    if (/risk|harm|adverse|negative|unfavorable|loss/.test(lower)) {
      bg = "#fef2f2"; border = "#fca5a5"; color = "#991b1b";       // risk
    } else if (/neutral|unchanged|housekeeping|admin/.test(lower)) {
      bg = "#f1f5f9"; border = "#cbd5e1"; color = "#334155";       // neutral
    }
    return '<span style="display:inline-flex;align-items:center;padding:3px 9px;font-size:10.5px;font-weight:800;letter-spacing:0.04em;background:' + bg + ';border:1px solid ' + border + ';color:' + color + ';line-height:1.25;border-radius:0;">' + _esEsc(raw || "—") + '</span>';
  };
  let rowsHtml = changes.map(function (c, i) {
    let zebra = (i % 2 === 0) ? "#ffffff" : "#f8fafc";
    return '<tr style="background:' + zebra + ';border-bottom:1px solid #e2e8f0;">' +
             '<td style="padding:11px 14px;font-weight:700;color:#0f172a;font-size:12px;vertical-align:top;width:30%;">' + _esEsc(c.clause) + '</td>' +
             '<td style="padding:11px 14px;color:#334155;font-size:12px;line-height:1.55;vertical-align:top;">' + _esEsc(c.change) + '</td>' +
             '<td style="padding:11px 14px;vertical-align:top;width:18%;text-align:right;">' + _impactPill(c.impact) + '</td>' +
           '</tr>';
  }).join("");
  let card = document.createElement("div");
  // No legacy classes — slide-in/tool-box have no v3 CSS, but if a
  // stray keyframe ever lands they'd transform the card mid-paint and
  // visually overlap whatever follows. Inline-only is safer.
  card.style.cssText = "background:#fff;border:1px solid #e2e8f0;border-left:4px solid #c9a227;box-shadow:0 6px 18px rgba(15,23,42,0.06);margin:0 0 18px 0;overflow:hidden;flex:0 0 auto;position:relative;z-index:0;";
  card.innerHTML =
    '<div style="padding:16px 20px 14px 20px;background:linear-gradient(135deg,#1e3a8a,#1565c0);color:#fff;display:flex;justify-content:space-between;align-items:flex-end;gap:10px;">' +
      '<div style="min-width:0;flex:1;">' +
        '<div style="font-size:10px;font-weight:800;opacity:0.82;text-transform:uppercase;letter-spacing:1.6px;">📊 Version Compare</div>' +
        '<div style="font-size:18px;font-weight:800;margin-top:4px;letter-spacing:0.01em;">Executive Summary</div>' +
      '</div>' +
      '<div style="flex-shrink:0;display:flex;align-items:center;gap:6px;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.4);padding:5px 10px;font-size:11px;font-weight:800;letter-spacing:0.04em;">' +
        '<span style="font-size:14px;font-weight:900;">' + changes.length + '</span>' +
        '<span style="opacity:0.85;text-transform:uppercase;font-size:10px;">change' + (changes.length === 1 ? '' : 's') + '</span>' +
      '</div>' +
    '</div>' +
    '<div style="padding:16px 20px 4px 20px;font-size:13px;color:#1e293b;line-height:1.6;">' + _esEsc(data.summary) + '</div>' +
    (changes.length
      ? ('<div style="padding:14px 20px 18px 20px;">' +
          '<table style="width:100%;border-collapse:collapse;font-size:12px;border:1px solid #e2e8f0;">' +
            '<thead><tr style="background:#f1f5f9;text-align:left;border-bottom:2px solid #cbd5e1;">' +
              '<th style="padding:9px 14px;font-size:10px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.08em;">Clause</th>' +
              '<th style="padding:9px 14px;font-size:10px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.08em;">Change</th>' +
              '<th style="padding:9px 14px;font-size:10px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.08em;text-align:right;">Impact</th>' +
            '</tr></thead>' +
            '<tbody>' + rowsHtml + '</tbody>' +
          '</table>' +
        '</div>')
      : '<div style="padding:6px 20px 18px 20px;font-size:12px;color:#94a3b8;font-style:italic;">No discrete clause-level changes were identified.</div>') +
    '';
  out.appendChild(card);
  // Action row — three platinum buttons, ALL EQUAL WIDTH, centered as
  // a tight group (NOT stretched across the panel). CSS grid with three
  // 1fr columns capped at 140px each gives true equal sizing regardless
  // of label length; justify-content:center keeps the group centered in
  // the row instead of left-aligning. Defensive top/bottom margin so
  // the row can't overlap the card above or the status bar below.
  // 2026-05-17 v16: Deep Analysis + Review Redline + Timeline buttons
  // all removed. Single Home button now — the executive summary is the
  // whole point of this view; the extra CTAs were noise.
  let actionRow = document.createElement("div");
  actionRow.style.cssText = "display:flex;justify-content:center;width:100%;margin:20px 0 24px 0;flex:0 0 auto;clear:both;position:relative;z-index:1;";
  let btnExtras = "display:inline-flex;align-items:center;justify-content:center;gap:6px;line-height:1.2;border-radius:0;min-width:140px;";
  let btnHome = document.createElement("button");
  btnHome.className = "btn-platinum";
  btnHome.style.cssText = btnExtras;
  btnHome.innerHTML = "<span>🏠</span><span>Home</span>";
  btnHome.title = "Back to dashboard";
  btnHome.onclick = function () {
    // eli.dashboard.goHome is the kernel's real home path (clears #output +
    // rebuilds the dashboard). The old eli.ui.showDashboard()/"ui.home" bus
    // calls don't exist, so Home only cleared the report and stranded the user.
    if (window.eli && window.eli.dashboard && typeof window.eli.dashboard.goHome === "function") {
      try { window.eli.dashboard.goHome(); return; } catch (_) {}
    }
    // Last-ditch fallback: clear the report so the user isn't stuck on it.
    try { if (window.eli && window.eli.ui && window.eli.ui.claimOutput) window.eli.ui.claimOutput(); } catch (_) {}
  };
  actionRow.appendChild(btnHome);
  out.appendChild(actionRow);
}

functions.showTemplateSelectionOverlay:
function showTemplateSelectionOverlay() {
  var overlay = document.createElement("div");
  overlay.className = "eli-overlay";
  var box = document.createElement("div");
  box.className = "tool-box slide-in";
  box.style.cssText = "background:white; width:700px; max-width:90%; height:80vh; padding:0; border-radius:0px; border:1px solid #1565c0; border-top:5px solid #1565c0; box-shadow:0 25px 60px rgba(0,0,0,0.4); display:flex; flex-direction:column;";
  box.innerHTML = `
    <div style="background: #f8f9fa; padding: 15px; border-bottom: 1px solid #ddd; display:flex; justify-content:space-between; align-items:center;">
        <div>
            <div style="font-weight:800; color:#1565c0; font-size:12px; text-transform:uppercase; letter-spacing:1px;">BUILD DRAFT LIBRARY</div>
            <div style="font-family:'Georgia', serif; font-size:16px; color:#333;">Select a Template to Load</div>
        </div>
        <button id="btnCloseTmpl" style="border:none; background:none; cursor:pointer; color:#999; font-weight:bold; font-size:18px;">✕</button>
    </div>
    <div style="flex:1; display:flex; overflow:hidden;">
        <div style="flex:1; border-right:1px solid #eee; display:flex; flex-direction:column; background:#fff;">
            <div style="padding:10px; background:#e3f2fd; color:#1565c0; font-size:11px; font-weight:700; border-bottom:1px solid #bbdefb; text-transform:uppercase;">
                🏗️ Core Templates (Master XML)
            </div>
            <div id="colCoreTemplates" style="flex:1; overflow-y:auto; padding:10px;">
                <div class="spinner" style="width:20px;height:20px;border-width:2px;border-color:#ccc transparent #ccc transparent; margin:20px auto; display:block;"></div>
            </div>
        </div>
        <div style="flex:1; display:flex; flex-direction:column; background:#fafafa;">
            <div style="padding:10px; background:#f5f5f5; color:#546e7a; font-size:11px; font-weight:700; border-bottom:1px solid #ddd; text-transform:uppercase;">
                📂 Prior Agreements (By Type)
            </div>
            <div id="colPriorAgreements" style="flex:1; overflow-y:auto; padding:10px;">
                <div class="spinner" style="width:20px;height:20px;border-width:2px;border-color:#ccc transparent #ccc transparent; margin:20px auto; display:block;"></div>
            </div>
        </div>
    </div>
    <div style="padding:15px; border-top:1px solid #ddd; background:#fff; text-align:right;">
        <span style="font-size:10px; color:#999; margin-right:10px;">Clicking a template will overwrite the current document body.</span>
        <button id="btnCancelTmpl" class="btn-secondary" style="width:auto; padding:10px 20px;">CANCEL</button>
    </div>
    `;
  overlay.appendChild(box);
  document.body.appendChild(overlay);
  function close() {
    overlay.remove();
    setLoading(!1);
  }
  document.getElementById("btnCloseTmpl").onclick = close;
  document.getElementById("btnCancelTmpl").onclick = close;
  window.eli.storage.getAll("bd_templates").then(function(_rows){return (_rows||[]).filter(function(_r){return _r&&typeof _r==="object"&&(!_r.id||String(_r.id).charAt(0)!=="_")})}).then(function (data) {
    var allTemplates = data || [];
    var coreContainer = document.getElementById("colCoreTemplates");
    var priorContainer = document.getElementById("colPriorAgreements");
    coreContainer.innerHTML = "";
    priorContainer.innerHTML = "";
    var coreList = allTemplates.filter(function (t) {
      return t.type === "MasterXML";
    });
    var priorList = allTemplates.filter(function (t) {
      return t.type !== "MasterXML";
    });
    if (coreList.length === 0) {
      coreContainer.innerHTML =
        "<div style='font-size:11px; color:#999; text-align:center; padding:20px;'>No Build Draft templates found.<br>Upload one in Settings.</div>";
    } else {
      coreList.forEach(function (t) {
        var el = createTemplateItem(t, overlay, "#1565c0");
        coreContainer.appendChild(el);
      });
    }
    if (priorList.length === 0) {
      priorContainer.innerHTML =
        "<div style='font-size:11px; color:#999; text-align:center; padding:20px;'>No prior agreements saved.</div>";
    } else {
      var groups = {};
      priorList.forEach(function (t) {
        var gName = (t.agreementType || "General").toUpperCase();
        if (!groups[gName]) groups[gName] = [];
        groups[gName].push(t);
      });
      Object.keys(groups)
        .sort()
        .forEach(function (gName) {
          var grpHeader = document.createElement("div");
          grpHeader.style.cssText = "font-size:10px; font-weight:800; color:#546e7a; margin-top:10px; margin-bottom:5px; padding-bottom:2px; border-bottom:1px solid #e0e0e0; text-transform:uppercase; letter-spacing:0.5px;";
          grpHeader.innerText = gName;
          priorContainer.appendChild(grpHeader);
          groups[gName].forEach(function (t) {
            var el = createTemplateItem(t, overlay, "#2e7d32");
            priorContainer.appendChild(el);
          });
        });
    }
  });
  function createTemplateItem(t, overlay, accentColor) {
    var div = document.createElement("div");
    var dateStr = t.savedDate || "Unknown Date";
    div.style.cssText =
      "padding: 10px; background: white; border: 1px solid #eee; border-left:3px solid " +
      accentColor +
      "; margin-bottom: 6px; border-radius: 4px; cursor: pointer; transition: all 0.1s;";
    div.innerHTML = `
          <div style="font-weight: 700; color: #37474f; font-size: 12px; line-height:1.3;">${t.name}</div>
          <div style="font-size: 10px; color: #90a4ae; margin-top: 3px;">${dateStr}</div>
      `;
    div.onmouseover = function () {
      this.style.background = "#e3f2fd";
      this.style.borderColor = "#90caf9";
      this.style.borderLeftColor = accentColor;
    };
    div.onmouseout = function () {
      this.style.background = "white";
      this.style.borderColor = "#eee";
      this.style.borderLeftColor = accentColor;
    };
    div.onclick = async function () {
      overlay.remove();
      showToast("📄 Loading " + t.name + "...");
      setLoading(!0, "template");
      try {
        if (t.type === "PriorAgreement" || t.content.trim().startsWith("{")) {
          await loadTemplateToWord(t.content);
        } else {
          await Word.run(async (context) => {
            var body = context.document.body;
            body.clear();
            body.insertOoxml(t.content, Word.InsertLocation.end);
            await context.sync();
          });
        }
        var stats = typeof getEliUserStats === "function" ? getEliUserStats() : null;
        if (stats && t.name) {
          var tmp = t.name.toUpperCase();
          if (!stats.draftTypesBuilt) stats.draftTypesBuilt = {};
          if (tmp.includes("NDA") || tmp.includes("NON-DISCLOSURE")) stats.draftTypesBuilt.NDA = true;
          if (tmp.includes("SERVICE")) stats.draftTypesBuilt.ServiceAgreement = true;
          if (tmp.includes("MTA") || tmp.includes("MATERIAL TRANSFER") || tmp.includes("TRANSFER"))
            stats.draftTypesBuilt.MTA = true;
          if (tmp.includes("AMEND") || tmp.includes("ADDENDUM")) stats.draftTypesBuilt.Amendment = true;
          _saveEliStats(stats);
        }
        if (typeof recordEliStat !== "undefined") window.eli.stats.record("draftsCreated");
        showToast("✅ Template Loaded!");
      } catch (e) {
        showToast("❌ Load Failed: " + e.message);
      }
      setLoading(!1);
    };
    return div;
  }
}

functions.compareLocateFromCard:
function compareLocateFromCard(
  searchText,
  clauseRef,
  btnElement,
  isDeletion,
  encodedDeletedSnippet,
  encodedOriginalSnippet,
  encodedNewSnippet
) {
  var deletedSnippet = "";
  var originalSnippet = "";
  var newSnippet = "";
  try {
    deletedSnippet = encodedDeletedSnippet ? decodeURIComponent(encodedDeletedSnippet) : "";
  } catch (e) {
    deletedSnippet = encodedDeletedSnippet || "";
  }
  try {
    originalSnippet = encodedOriginalSnippet ? decodeURIComponent(encodedOriginalSnippet) : "";
  } catch (e) {
    originalSnippet = encodedOriginalSnippet || "";
  }
  try {
    newSnippet = encodedNewSnippet ? decodeURIComponent(encodedNewSnippet) : "";
  } catch (e) {
    newSnippet = encodedNewSnippet || "";
  }
  // 2026-05-16: Tier 0 — if searchText IS an anchor id (ELI_IDX_<n>,
  // emitted by the AI post-prompt-migration), jump directly via
  // highlightAnchor. One Word.run vs the body.search cascade's load+
  // sync chain. Falls through to locateCompareLikeTrackChanges if
  // the anchor is missing (e.g. doc was edited, bookmark stripped),
  // which exhausts the section-jump + tracked-change + text-search tiers.
  var st = String(searchText || "").trim();
  var looksLikeAnchor = /^_?ELI_(IDX|LR|ER|QA)_[A-Za-z0-9_]*$/.test(st);
  function _fallbackToTextCascade() {
    var textToFind = looksLikeAnchor
      ? (originalSnippet || newSnippet || deletedSnippet || clauseRef || "")
      : st;
    locateCompareLikeTrackChanges(textToFind, btnElement, clauseRef, clauseRef, {
      isDeletion: !!isDeletion,
      deletedSnippet: deletedSnippet,
      originalSnippet: originalSnippet,
      newSnippet: newSnippet,
      hasTrackedPriority: !!isDeletion || (originalSnippet && newSnippet),
    });
  }
  if (looksLikeAnchor && window.eli && window.eli.host && typeof window.eli.host.highlightAnchor === "function") {
    return window.eli.host.highlightAnchor(st).then(function () {
      if (typeof showToast === "function") showToast("📍 Jumped to clause", "ok");
      try { window.eli.log.event("tool", "compare_locate_anchor_hit", { id: st }); } catch (_) {}
    }).catch(function () {
      try { window.eli.log.event("tool", "compare_locate_anchor_miss", { id: st }); } catch (_) {}
      _fallbackToTextCascade();
    });
  }
  _fallbackToTextCascade();
}

functions.showCompareSettings:
function showCompareSettings() {
  var eli = window.eli;
  var STORE = window.STORE_TEMPLATES || "templates";

  // ─── Helpers ─────────────────────────────────────────────────────
  function _getAll() {
    return eli.storage.getAll(STORE).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
      });
    });
  }
  function _putAll(rows) {
    // STORE has out-of-line keyPath (autoincrement-ish). Easiest path:
    // clearStore + put each. The store is small (dozens of rows max).
    return eli.storage.clearStore(STORE).then(function () {
      var p = Promise.resolve();
      (rows || []).forEach(function (row) {
        p = p.then(function () { return eli.storage.put(STORE, row); });
      });
      return p;
    });
  }
  function _esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function _toast(msg, kind) {
    if (typeof window.showToast === "function") window.showToast(msg, kind || "info");
  }

  // ─── Overlay ─────────────────────────────────────────────────────
  // Close any existing instance first (re-render after upload/delete).
  var existing = document.getElementById("_eli3_cmp_settings_overlay");
  if (existing && existing.parentNode) existing.parentNode.removeChild(existing);

  var ov = document.createElement("div");
  ov.id = "_eli3_cmp_settings_overlay";
  ov.style.cssText =
    "position:fixed;inset:0;z-index:99999;background:rgba(15,23,42,0.55);" +
    "display:flex;align-items:center;justify-content:center;padding:20px;" +
    "font-family:Inter,'Segoe UI',system-ui,sans-serif;";

  ov.innerHTML =
    '<div style="background:#fff;width:min(560px,96vw);max-height:92vh;display:flex;' +
         'flex-direction:column;border:1px solid #cbd5e1;box-shadow:0 24px 60px rgba(15,23,42,0.45);">' +
      // Header
      '<div style="padding:14px 18px;background:linear-gradient(135deg,#0d1b2a,#1b263b);color:#fff;' +
           'display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:#c9a227;">' +
            'Settings · Compare Draft' +
          '</div>' +
          '<div style="font:800 17px/1.2 Inter,sans-serif;margin-top:2px;">Templates</div>' +
        '</div>' +
        '<button id="_eli3_cmp_set_close" type="button" aria-label="Close" ' +
                'style="background:transparent;color:#fff;border:1px solid #475569;width:28px;height:28px;' +
                       'cursor:pointer;font:700 14px/1 Inter,sans-serif;">×</button>' +
      '</div>' +
      // Body (scrollable)
      '<div id="_eli3_cmp_set_body" style="padding:14px 16px;overflow-y:auto;flex:1;background:#f8fafc;">' +
        // ─── Templates list ──────────────────────────────────────
        '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:14px;">' +
          '<div style="padding:10px 14px;display:flex;justify-content:space-between;align-items:center;' +
                       'background:#f1f5f9;border-bottom:1px solid #e2e8f0;">' +
            '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1e293b;">' +
              '📚 Stored templates' +
            '</div>' +
            '<button id="_eli3_cmp_index_all" type="button" ' +
                    'style="font:700 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;' +
                           'padding:6px 10px;background:linear-gradient(180deg,#fef3c7,#fde68a);' +
                           'border:1px solid #d97706;color:#78350f;cursor:pointer;">' +
              '🔖 Index unindexed' +
            '</button>' +
          '</div>' +
          '<div id="_eli3_cmp_set_list" style="max-height:240px;overflow-y:auto;"></div>' +
        '</div>' +
        // ─── Add single ──────────────────────────────────────────
        '<div style="background:#fff;border:1px solid #e2e8f0;padding:12px 14px;margin-bottom:14px;">' +
          '<div style="font:800 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1565c0;margin-bottom:8px;">' +
            'Add single template' +
          '</div>' +
          '<input id="_eli3_cmp_set_name" type="text" placeholder="Template name (e.g. NDA 2025)" ' +
                 'style="width:100%;padding:8px 10px;font:500 12px/1.3 Inter,sans-serif;border:1px solid #cbd5e1;margin-bottom:8px;">' +
          '<div style="display:flex;gap:6px;align-items:center;">' +
            '<input id="_eli3_cmp_set_file" type="file" accept=".docx,.html,.txt" ' +
                   'style="font:500 11px/1.3 Inter,sans-serif;flex:1;">' +
            '<button id="_eli3_cmp_set_upload" type="button" ' +
                    'style="font:700 11px/1 Inter,sans-serif;padding:8px 14px;background:#1565c0;color:#fff;border:none;cursor:pointer;">' +
              'Upload' +
            '</button>' +
          '</div>' +
          '<div id="_eli3_cmp_set_status" style="font:500 10px/1.4 Inter,sans-serif;color:#64748b;margin-top:6px;min-height:14px;"></div>' +
        '</div>' +
        // ─── Bulk import ─────────────────────────────────────────
        '<div style="background:#fff;border:1px dashed #cbd5e1;padding:12px 14px;">' +
          '<div style="font:800 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#475569;margin-bottom:8px;">' +
            'Bulk import (JSON)' +
          '</div>' +
          '<div style="display:flex;gap:6px;align-items:center;">' +
            '<input id="_eli3_cmp_set_bulk" type="file" accept=".json" ' +
                   'style="font:500 11px/1.3 Inter,sans-serif;flex:1;">' +
            '<button id="_eli3_cmp_set_bulk_btn" type="button" ' +
                    'style="font:700 11px/1 Inter,sans-serif;padding:8px 14px;background:#475569;color:#fff;border:none;cursor:pointer;">' +
              'Import' +
            '</button>' +
          '</div>' +
          '<div style="font:500 9.5px/1.4 Inter,sans-serif;color:#94a3b8;margin-top:6px;">' +
            'Array of {name, content, type?, library?} objects.' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';

  document.body.appendChild(ov);

  // ─── Wire close ──────────────────────────────────────────────────
  function _close() { if (ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelector("#_eli3_cmp_set_close").onclick = _close;
  ov.onclick = function (e) { if (e.target === ov) _close(); };

  // ─── Render templates list ───────────────────────────────────────
  function _renderList(rows) {
    var listEl = document.getElementById("_eli3_cmp_set_list");
    if (!listEl) return;
    if (!rows || !rows.length) {
      listEl.innerHTML =
        '<div style="padding:24px 14px;font:500 12px/1.4 Inter,sans-serif;color:#94a3b8;text-align:center;">' +
          '<div style="font-size:22px;margin-bottom:6px;">📂</div>' +
          'No templates saved yet. Upload one below to get started.' +
        '</div>';
      return;
    }
    var html = "";
    rows.forEach(function (t, idx) {
      var indexed = !!t.indexed;
      var sectionCount = t.sectionCount || 0;
      var badgeHtml = indexed
        ? '<span style="font:700 9px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;' +
                'padding:3px 6px;background:#dcfce7;color:#15803d;border:1px solid #86efac;">' +
            '✓ Indexed · ' + sectionCount + ' sections' +
          '</span>'
        : '<span style="font:700 9px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;' +
                'padding:3px 6px;background:#fef3c7;color:#92400e;border:1px solid #fde68a;">' +
            'Not indexed' +
          '</span>';
      var typeLbl = t.agreementType || t.type || "";
      var typeTag = typeLbl
        ? ' <span style="font:500 10px/1.2 Inter,sans-serif;color:#64748b;">(' + _esc(typeLbl) + ')</span>'
        : "";
      // Detect content kind for the Index button. mammoth-extracted text or
      // anything that isn't a JSON envelope is fine — we'll insert as text.
      // For now every row gets an Index button; if it's non-.docx we still
      // let the user try and the indexer will work on whatever text loads.
      html +=
        '<div data-cmp-row="' + idx + '" ' +
             'style="padding:10px 14px;border-bottom:1px solid #f1f5f9;display:flex;' +
                    'justify-content:space-between;align-items:center;gap:10px;">' +
          '<div style="flex:1;min-width:0;">' +
            '<div style="font:700 12px/1.3 Inter,sans-serif;color:#0f172a;' +
                         'white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' +
              _esc(t.name || "Template " + (idx + 1)) + typeTag +
            '</div>' +
            '<div style="margin-top:4px;">' + badgeHtml + '</div>' +
          '</div>' +
          '<div style="display:flex;gap:6px;flex-shrink:0;">' +
            '<button data-cmp-act="index" data-idx="' + idx + '" type="button" ' +
                    'style="font:700 10px/1 Inter,sans-serif;letter-spacing:0.3px;text-transform:uppercase;' +
                           'padding:6px 10px;background:linear-gradient(180deg,#fff,#f1f5f9);' +
                           'border:1px solid #cbd5e1;color:#1e293b;cursor:pointer;">' +
              (indexed ? '🔖 Re-index' : '🔖 Index') +
            '</button>' +
            '<button data-cmp-act="delete" data-idx="' + idx + '" type="button" aria-label="Delete" ' +
                    'style="font:700 12px/1 Inter,sans-serif;padding:6px 8px;background:#fee2e2;' +
                           'border:1px solid #fecaca;color:#b91c1c;cursor:pointer;">🗑️</button>' +
          '</div>' +
        '</div>';
    });
    listEl.innerHTML = html;
    // Wire row buttons.
    listEl.querySelectorAll('button[data-cmp-act="delete"]').forEach(function (btn) {
      btn.onclick = function () {
        var i = parseInt(btn.getAttribute("data-idx"), 10);
        var row = rows[i];
        var name = (row && row.name) || "this template";
        if (typeof eli.ui.confirm === "function") {
          eli.ui.confirm({
            title: "Delete template?",
            message: 'Permanently delete "' + name + '" from your Compare templates?',
            primaryLabel: "Delete",
            danger: true,
          }).then(function (ok) {
            if (!ok) return;
            rows.splice(i, 1);
            _putAll(rows).then(function () {
              _toast("🗑️ Deleted: " + name, "ok");
              _refresh();
            });
          });
        } else {
          rows.splice(i, 1);
          _putAll(rows).then(function () { _toast("🗑️ Deleted: " + name, "ok"); _refresh(); });
        }
      };
    });
    listEl.querySelectorAll('button[data-cmp-act="index"]').forEach(function (btn) {
      btn.onclick = function () {
        var i = parseInt(btn.getAttribute("data-idx"), 10);
        var row = rows[i];
        if (!row) return;
        _startIndexFlow(row);
      };
    });
  }

  // ─── Refresh (re-read + render) ──────────────────────────────────
  function _refresh() {
    _getAll().then(_renderList).catch(function () { _renderList([]); });
  }
  _refresh();

  // ─── Upload single ───────────────────────────────────────────────
  ov.querySelector("#_eli3_cmp_set_upload").onclick = function () {
    var nameInput = ov.querySelector("#_eli3_cmp_set_name");
    var fileInput = ov.querySelector("#_eli3_cmp_set_file");
    var status = ov.querySelector("#_eli3_cmp_set_status");
    var name = (nameInput.value || "").trim();
    if (!name) { status.textContent = "⚠️ Enter a name first."; status.style.color = "#b91c1c"; return; }
    if (!fileInput.files || !fileInput.files[0]) {
      status.textContent = "⚠️ Pick a file first."; status.style.color = "#b91c1c"; return;
    }
    if (typeof window.handleFileSelect !== "function") {
      status.textContent = "⚠️ File reader not loaded yet. Try again in a moment."; status.style.color = "#b91c1c";
      return;
    }
    status.textContent = "⏳ Reading file…"; status.style.color = "#64748b";
    window.handleFileSelect(fileInput.files[0], function (text) {
      var content = typeof text === "string" ? text : "";
      if (!content) {
        status.textContent = "⚠️ Couldn't read file content."; status.style.color = "#b91c1c";
        return;
      }
      _getAll().then(function (rows) {
        rows = rows || [];
        rows.push({
          name: name,
          content: content,
          type: "General",
          library: "User",
          indexed: false,
          uploadedAt: new Date().toISOString(),
        });
        _putAll(rows).then(function () {
          status.textContent = "✅ Saved."; status.style.color = "#15803d";
          nameInput.value = "";
          fileInput.value = "";
          _refresh();
        });
      });
    });
  };

  // ─── Bulk JSON import ────────────────────────────────────────────
  ov.querySelector("#_eli3_cmp_set_bulk_btn").onclick = function () {
    var inp = ov.querySelector("#_eli3_cmp_set_bulk");
    if (!inp.files || !inp.files[0]) { _toast("⚠️ Pick a JSON file first.", "warn"); return; }
    var reader = new FileReader();
    reader.onload = function (e) {
      var imported;
      try {
        var parsed = JSON.parse(e.target.result);
        if (!Array.isArray(parsed)) throw new Error("Root must be an array.");
        imported = parsed.filter(function (r) {
          return r && typeof r === "object" && r.name && (r.content || r.text);
        }).map(function (r) {
          return {
            name: String(r.name).trim(),
            content: String(r.content || r.text || ""),
            type: String(r.type || "General"),
            library: String(r.library || "Imported"),
            indexed: false,
            uploadedAt: new Date().toISOString(),
          };
        });
        if (!imported.length) throw new Error("No valid {name, content} entries found.");
      } catch (err) {
        _toast("❌ " + err.message, "err");
        return;
      }
      _getAll().then(function (rows) {
        rows = (rows || []).concat(imported);
        _putAll(rows).then(function () {
          _toast("✅ Imported " + imported.length + " templates.", "ok");
          inp.value = "";
          _refresh();
        });
      });
    };
    reader.onerror = function () { _toast("❌ Couldn't read JSON file.", "err"); };
    reader.readAsText(inp.files[0]);
  };

  // ─── Bulk re-index (iterate unindexed rows) ──────────────────────
  ov.querySelector("#_eli3_cmp_index_all").onclick = function () {
    _getAll().then(function (rows) {
      var unindexed = (rows || []).filter(function (r) { return !r.indexed; });
      if (!unindexed.length) {
        _toast("All templates already indexed.", "info");
        return;
      }
      // We can only index one at a time (each opens the indexer + waits
      // for user save-back). Just pick the first unindexed one and start
      // that flow; user re-clicks for the next one.
      if (typeof eli.ui.confirm === "function") {
        eli.ui.confirm({
          title: "Index " + unindexed.length + " templates?",
          message:
            "Indexing is one template at a time — you'll load each into Word, " +
            "review its section breaks, then save it back. Start with the first " +
            "unindexed template ('" + (unindexed[0].name || "untitled") + "') now?",
          primaryLabel: "Start",
        }).then(function (ok) { if (ok) _startIndexFlow(unindexed[0]); });
      } else {
        _startIndexFlow(unindexed[0]);
      }
    });
  };
}

// ─────────────────────────────────────────────────────────────────────
// INDEX FLOW
// ─────────────────────────────────────────────────────────────────────
// 1. Stash {id-equivalent + name} in window._eli3_cmp_indexing
// 2. Load the template content into Word (envelope or plain-text path)
// 3. Open template_indexer (it scans the live doc)
// 4. Inject a floating "Save back to Compare" pill at top of taskpane
// 5. User indexes + hits Save & Apply (writes bookmarks + customXmlParts)
// 6. User clicks pill → capture doc body + customXmlParts → write back
//    to STORE_TEMPLATES → remove pill → toast
// ─────────────────────────────────────────────────────────────────────

functions._startIndexFlow:
function _startIndexFlow(row) {
  var eli = window.eli;
  if (!row) return;
  // The IDB store has no stable id — match by name (the unique-ish key
  // v2 used). Stash name so save-back finds the right row.
  window._eli3_cmp_indexing = {
    name: row.name,
    originalIndexedAt: row.indexedAt || null,
  };

  // Close the settings overlay so the user sees Word + indexer.
  var ov = document.getElementById("_eli3_cmp_settings_overlay");
  if (ov && ov.parentNode) ov.parentNode.removeChild(ov);

  // Load template into Word. Detect envelope vs plain text.
  var content = row.content || "";
  var loadP;
  if (typeof content === "string" && content.length > 0 && content.charAt(0) === "{") {
    // Looks like an envelope — let build_draft handle it (header/footer,
    // customXmlParts, the whole thing).
    if (eli.dispatch) {
      loadP = Promise.resolve(eli.dispatch("build_draft", "loadTemplateRaw", content));
    } else {
      loadP = Promise.reject(new Error("build_draft not available"));
    }
  } else {
    // Plain text body — insert as-is into Word.body. Indexer's structural
    // map walker will pick up the paragraphs.
    loadP = eli.host.runRaw("compare:cmp_load_for_index", function (ctx) {
      var body = ctx.document.body;
      body.clear();
      body.insertText(content, "Replace");
      return ctx.sync();
    });
  }

  if (window.showToast) window.showToast("⏳ Loading '" + row.name + "' into Word…", "info");

  loadP
    .then(function () {
      // Open Template Indexer. Both demand-tier — kernel will eval bundle
      // on first dispatch.
      if (eli.dispatch) {
        var r = eli.dispatch("tile", "app_template_indexer");
        if (r === undefined) {
          // Fallback: direct function.
          if (typeof window.showTemplateIndexer === "function") window.showTemplateIndexer();
        }
      }
      // Inject the floating save-back pill after a short delay (let
      // indexer paint first).
      setTimeout(_installSaveBackPill, 400);
    })
    .catch(function (err) {
      if (window.showToast) window.showToast("⚠️ Couldn't load template: " + (err && err.message || "unknown"), "err");
      window._eli3_cmp_indexing = null;
    });
}

functions._installSaveBackPill:
function _installSaveBackPill() {
  // Remove any prior pill.
  var prior = document.getElementById("_eli3_cmp_saveback_pill");
  if (prior && prior.parentNode) prior.parentNode.removeChild(prior);

  var info = window._eli3_cmp_indexing;
  if (!info) return;

  var pill = document.createElement("div");
  pill.id = "_eli3_cmp_saveback_pill";
  pill.style.cssText =
    "position:fixed;top:14px;right:14px;z-index:2147483647;" +
    "background:linear-gradient(180deg,#fef3c7,#fde68a);border:1.5px solid #d97706;" +
    "padding:10px 14px;box-shadow:0 8px 24px rgba(217,119,6,0.35);" +
    "font:700 11px/1.3 Inter,'Segoe UI',sans-serif;color:#78350f;" +
    "display:flex;align-items:center;gap:10px;max-width:300px;cursor:default;";
  pill.innerHTML =
    '<div style="flex:1;min-width:0;">' +
      '<div style="font:800 9px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#92400e;">' +
        'Compare indexer · pending' +
      '</div>' +
      '<div style="margin-top:3px;font:700 11px/1.3 Inter,sans-serif;color:#78350f;' +
                   'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
        (info.name || "Template") +
      '</div>' +
    '</div>' +
    '<button id="_eli3_cmp_saveback_btn" type="button" ' +
            'style="font:800 10px/1 Inter,sans-serif;letter-spacing:0.3px;text-transform:uppercase;' +
                   'padding:7px 10px;background:#15803d;color:#fff;border:none;cursor:pointer;">' +
      '💾 Save back' +
    '</button>' +
    '<button id="_eli3_cmp_saveback_x" type="button" aria-label="Cancel" ' +
            'style="font:800 14px/1 Inter,sans-serif;background:transparent;border:none;color:#78350f;cursor:pointer;">×</button>';
  document.body.appendChild(pill);

  pill.querySelector("#_eli3_cmp_saveback_btn").onclick = _doSaveBack;
  pill.querySelector("#_eli3_cmp_saveback_x").onclick = function () {
    if (pill.parentNode) pill.parentNode.removeChild(pill);
    window._eli3_cmp_indexing = null;
    if (window.showToast) window.showToast("Indexing cancelled — template not saved back.", "warn");
  };
}

functions._doSaveBack:
function _doSaveBack() {
  var eli = window.eli;
  var info = window._eli3_cmp_indexing;
  if (!info) {
    if (window.showToast) window.showToast("No indexing session in progress.", "warn");
    return;
  }
  var btn = document.getElementById("_eli3_cmp_saveback_btn");
  if (btn) { btn.disabled = true; btn.textContent = "⏳ Saving…"; }

  // Capture body OOXML + customXmlParts via two short runRaw passes
  // (same shape build_draft uses). Then extract plain text for the
  // `content` field that Compare's diff engine reads.
  eli.host.runRaw("compare:cmp_indexer_save_body", function (ctx) {
    var bodyOoxml = ctx.document.body.getOoxml();
    var bodyText = ctx.document.body.load("text");
    return ctx.sync().then(function () {
      return { body: bodyOoxml.value, text: ctx.document.body.text || "" };
    });
  }).then(function (bodyResult) {
    return eli.host.runRaw("compare:cmp_indexer_save_xml", function (ctx) {
      var parts = ctx.document.customXmlParts;
      parts.load("items/namespaceUri,items/id");
      return ctx.sync().then(function () {
        var items = parts.items || [];
        if (!items.length) return { body: bodyResult.body, text: bodyResult.text, customXmlParts: [] };
        var xmlReqs = items.map(function (p) {
          var info2 = { ns: "", xmlReq: null };
          try { info2.ns = p.namespaceUri || ""; } catch (e) {}
          try { info2.xmlReq = p.getXml(); } catch (e) {}
          return info2;
        });
        return ctx.sync().then(function () {
          // Same Word built-in NS filter build_draft uses.
          var BUILTIN = {
            "http://schemas.openxmlformats.org/package/2006/metadata/core-properties": 1,
            "http://schemas.openxmlformats.org/officeDocument/2006/extended-properties": 1,
            "http://schemas.microsoft.com/office/2006/coverPageProps": 1,
          };
          function _nsFromXml(xml) {
            if (!xml) return "";
            var m = xml.match(/xmlns(?::[A-Za-z0-9]+)?\s*=\s*"([^"]+)"/);
            return m ? m[1] : "";
          }
          var keepers = xmlReqs
            .map(function (r) {
              var xml = (r.xmlReq && r.xmlReq.value) || "";
              if (!xml) return null;
              var ns = r.ns || _nsFromXml(xml);
              if (BUILTIN[ns]) return null;
              return { namespaceUri: ns, xml: xml };
            })
            .filter(Boolean);
          return { body: bodyResult.body, text: bodyResult.text, customXmlParts: keepers };
        });
      });
    });
  }).then(function (captured) {
    // Count sections from indexer's customXmlParts (eli template-indexer NS).
    var sectionCount = 0;
    var INDEXER_NS = "http://eli.app/template-indexer/v1";
    (captured.customXmlParts || []).forEach(function (p) {
      if (p.namespaceUri === INDEXER_NS) {
        var matches = (p.xml || "").match(/<section\b/g);
        if (matches) sectionCount = matches.length;
      }
    });

    // Write back to STORE_TEMPLATES by matching name.
    var STORE = window.STORE_TEMPLATES || "templates";
    return eli.storage.getAll(STORE).then(function (rows) {
      rows = (rows || []).filter(function (r) {
        return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
      });
      var idx = -1;
      for (var i = 0; i < rows.length; i++) {
        if (rows[i] && rows[i].name === info.name) { idx = i; break; }
      }
      if (idx < 0) {
        throw new Error("Couldn't find the original template '" + info.name + "' in storage.");
      }
      var existing = rows[idx];
      existing.content = captured.text;
      existing.envelope = JSON.stringify({
        body: captured.body,
        customXmlParts: captured.customXmlParts || [],
      });
      existing.indexed = sectionCount > 0;
      existing.sectionCount = sectionCount;
      existing.indexedAt = new Date().toISOString();

      // Clear store + re-put everything (STORE has no stable id keypath).
      return eli.storage.clearStore(STORE).then(function () {
        var p = Promise.resolve();
        rows.forEach(function (r) {
          p = p.then(function () { return eli.storage.put(STORE, r); });
        });
        return p;
      }).then(function () {
        return { name: info.name, sectionCount: sectionCount };
      });
    });
  }).then(function (result) {
    var pill = document.getElementById("_eli3_cmp_saveback_pill");
    if (pill && pill.parentNode) pill.parentNode.removeChild(pill);
    window._eli3_cmp_indexing = null;
    if (window.showToast) {
      window.showToast(
        "✅ Saved '" + result.name + "' (" + result.sectionCount + " sections) back to Compare templates.",
        "ok"
      );
    }
  }).catch(function (err) {
    var btn2 = document.getElementById("_eli3_cmp_saveback_btn");
    if (btn2) { btn2.disabled = false; btn2.textContent = "💾 Save back"; }
    if (window.showToast) {
      window.showToast("⚠️ Save-back failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

// Expose for the bundler/eli.register pattern.
if (typeof window !== "undefined") {
  window.showCompareSettings = showCompareSettings;
}

functions._tpDecodeXmlEntities:
function _tpDecodeXmlEntities(s) {
  return String(s)
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}

// Extract per-paragraph redline spans. Returns:
//   [{ idx, paraId, acceptedText, originalText, pendingIns:[{text,author,date},...], pendingDel:[...] }, ...]

functions._eliExtractParagraphRedlineSpans:
function _eliExtractParagraphRedlineSpans(xml) {
  if (!xml) return [];
  // _tpStripOoxmlNoise is shimmed in compare/init.js. Tolerate its absence.
  var normalized = typeof window._tpStripOoxmlNoise === "function"
    ? window._tpStripOoxmlNoise(xml)
    : xml;
  var pRegex = /<w:p\b[^>]*\/>|<w:p\b[^>]*>[\s\S]*?<\/w:p>/g;
  var paragraphs = [];
  var pm;
  var pIdx = 0;
  var pullText = function (frag) {
    var rg = /<w:(?:t|delText)\b[^>]*>([\s\S]*?)<\/w:(?:t|delText)>/g;
    var parts = [];
    var m;
    while ((m = rg.exec(frag)) !== null) parts.push(_tpDecodeXmlEntities(m[1]));
    return parts.join("").replace(/\s+/g, " ").trim();
  };
  var attrs = function (tag) {
    var a = (tag.match(/w:author="([^"]*)"/) || [])[1] || "";
    var d = (tag.match(/w:date="([^"]*)"/) || [])[1] || "";
    return { author: a, date: d };
  };
  while ((pm = pRegex.exec(normalized)) !== null) {
    var rawPXml = pm[0];
    var paraId = "";
    var openTagMatch = rawPXml.match(/^<w:p\b[^>]*>/);
    if (openTagMatch) {
      var idMatch = openTagMatch[0].match(/w14:paraId="([^"]*)"/);
      if (idMatch) paraId = idMatch[1];
    }
    var pXml = rawPXml
      .replace(/<w:pPr>[\s\S]*?<\/w:pPr>/g, "")
      .replace(/<w:rPr>[\s\S]*?<\/w:rPr>/g, "");
    var pendingIns = [];
    var pendingDel = [];
    var insRe = /<w:ins\b([^>]*)>([\s\S]*?)<\/w:ins>/g;
    var im;
    while ((im = insRe.exec(pXml)) !== null) {
      var insTxt = pullText(im[2]);
      if (insTxt) pendingIns.push(Object.assign({ text: insTxt }, attrs("<w:ins" + im[1] + ">")));
    }
    var delRe = /<w:del\b([^>]*)>([\s\S]*?)<\/w:del>/g;
    var dm;
    while ((dm = delRe.exec(pXml)) !== null) {
      var delTxt = pullText(dm[2]);
      if (delTxt) pendingDel.push(Object.assign({ text: delTxt }, attrs("<w:del" + dm[1] + ">")));
    }
    var acceptedFrag = pXml.replace(/<w:del\b[^>]*>[\s\S]*?<\/w:del>/g, "");
    var acceptedText = pullText(acceptedFrag);
    var originalFrag = pXml.replace(/<w:ins\b[^>]*>[\s\S]*?<\/w:ins>/g, "");
    var originalText = pullText(originalFrag);
    paragraphs.push({
      idx: pIdx++,
      paraId: paraId,
      acceptedText: acceptedText,
      originalText: originalText,
      pendingIns: pendingIns,
      pendingDel: pendingDel,
    });
  }
  return paragraphs;
}

// Compare two snapshots' bodyOoxml. Returns:
//   { transitions: [...], summary: { accepted, rejected, newRedlines, retained, unmarked } }
// Each transition: { type, paragraphIdx, paraId, text, author, date, source }
// type ∈ accepted-insertion | rejected-insertion | accepted-deletion |
//        rejected-deletion | new-insertion | new-deletion |
//        retained-pending-insertion | retained-pending-deletion |
//        unmarked-change

functions.compareSnapshotsRedlineAware:
function compareSnapshotsRedlineAware(v1Snap, v2Snap) {
  var v1Xml = (v1Snap && v1Snap.bodyOoxml) || "";
  var v2Xml = (v2Snap && v2Snap.bodyOoxml) || "";
  if (!v1Xml || !v2Xml) {
    return {
      transitions: [],
      summary: { accepted: 0, rejected: 0, newRedlines: 0, retained: 0, unmarked: 0 },
      error: !v1Xml && !v2Xml ? "Both snapshots are missing bodyOoxml" :
        (!v1Xml ? "v1 snapshot has no bodyOoxml" : "v2 snapshot has no bodyOoxml"),
    };
  }
  var v1Paras = _eliExtractParagraphRedlineSpans(v1Xml);
  var v2Paras = _eliExtractParagraphRedlineSpans(v2Xml);
  var transitions = [];
  var counts = { accepted: 0, rejected: 0, newRedlines: 0, retained: 0, unmarked: 0 };
  var normText = function (s) { return String(s || "").replace(/\s+/g, " ").trim().toLowerCase(); };
  var redlineKey = function (entry) { return normText(entry.text) + " " + (entry.author || ""); };
  var collectRedlines = function (paras, source) {
    var ins = [], del = [];
    paras.forEach(function (p, idx) {
      p.pendingIns.forEach(function (e) {
        ins.push({ text: e.text, author: e.author, date: e.date, paraId: p.paraId, paraIdx: idx, source: source });
      });
      p.pendingDel.forEach(function (e) {
        del.push({ text: e.text, author: e.author, date: e.date, paraId: p.paraId, paraIdx: idx, source: source });
      });
    });
    return { ins: ins, del: del };
  };
  var v1R = collectRedlines(v1Paras, "v1");
  var v2R = collectRedlines(v2Paras, "v2");
  var buildSet = function (arr) {
    var map = {};
    arr.forEach(function (e) { var k = redlineKey(e); if (!map[k]) map[k] = e; });
    return map;
  };
  var v1InsSet = buildSet(v1R.ins);
  var v1DelSet = buildSet(v1R.del);
  var v2InsSet = buildSet(v2R.ins);
  var v2DelSet = buildSet(v2R.del);
  var v2CleanText = v2Paras.map(function (p) { return p.acceptedText || ""; }).join(" ");
  var v2CleanLower = normText(v2CleanText);
  var v1CleanLower = normText(v1Paras.map(function (p) { return p.acceptedText || ""; }).join(" "));
  // 2026-05-17 v14: robust per-paragraph alignment. The old approach
  // (paraId match only, with global-substring fallback) misclassified
  // common-word deletions ("immediately", "promptly") as rejected
  // whenever the word existed somewhere else in v2. Fix: build an
  // explicit v1↔v2 paragraph alignment using paraId FIRST, then content
  // similarity for paragraphs without a paraId match. Every membership
  // check then happens against ONE specific aligned paragraph — no
  // global substring search means no cross-paragraph false positives.
  var v2ParaById = {};
  v2Paras.forEach(function (p) { if (p.paraId) v2ParaById[p.paraId] = p; });
  var v1ParaById = {};
  v1Paras.forEach(function (p) { if (p.paraId) v1ParaById[p.paraId] = p; });
  // Word-set overlap score (Jaccard-ish): how similar are two paragraph
  // texts? Used for content-based fallback alignment. Words of length
  // ≤2 are skipped — they're "the / a / an / of / to" noise that
  // dominates short paragraphs and washes out the score.
  var _tokenize = function (s) {
    return String(s || "").toLowerCase().split(/\s+/).filter(function (w) { return w && w.length > 2; });
  };
  var _wordOverlapScore = function (a, b) {
    var ta = _tokenize(a), tb = _tokenize(b);
    if (!ta.length || !tb.length) return 0;
    var setA = {};
    ta.forEach(function (w) { setA[w] = (setA[w] || 0) + 1; });
    var hit = 0, totalB = 0;
    tb.forEach(function (w) {
      totalB++;
      if (setA[w] && setA[w] > 0) { hit++; setA[w]--; }
    });
    // Score = hits / max(|a|, |b|) — symmetric, rewards full overlap.
    return hit / Math.max(ta.length, totalB);
  };
  // Build v1→v2 paragraph alignment.
  //   1st pass: paraId direct hit.
  //   2nd pass: content similarity ≥ 0.5 against any v2 paragraph not
  //             already claimed by a v1 paragraph. Greedy on
  //             best-score-first to avoid cascade misalignments.
  var v1ToV2Aligned = new Array(v1Paras.length).fill(null);
  var v2Claimed = new Array(v2Paras.length).fill(false);
  // Pass 1: paraId direct alignment.
  v1Paras.forEach(function (p1, i1) {
    if (!p1.paraId) return;
    var p2 = v2ParaById[p1.paraId];
    if (!p2) return;
    v1ToV2Aligned[i1] = p2;
    v2Claimed[p2.idx] = true;
  });
  // Pass 2: content-similarity for unmatched v1 paragraphs. For each
  // unmatched v1 paragraph, find the best-scoring unclaimed v2 paragraph
  // above the 0.5 threshold; if found, claim it. (0.5 = at least half
  // the meaningful words overlap — strong enough to be the "same
  // paragraph" even after counterparty edits.)
  v1Paras.forEach(function (p1, i1) {
    if (v1ToV2Aligned[i1]) return;
    var bestScore = 0;
    var bestIdx = -1;
    var p1Text = (p1.acceptedText || "") + " " + (p1.originalText || "");
    if (!p1Text.trim()) return;
    for (var j = 0; j < v2Paras.length; j++) {
      if (v2Claimed[j]) continue;
      var p2 = v2Paras[j];
      var p2Text = (p2.acceptedText || "") + " " + (p2.originalText || "");
      var s = _wordOverlapScore(p1Text, p2Text);
      if (s > bestScore) { bestScore = s; bestIdx = j; }
    }
    if (bestScore >= 0.5 && bestIdx >= 0) {
      v1ToV2Aligned[i1] = v2Paras[bestIdx];
      v2Claimed[bestIdx] = true;
    }
  });
  // Reverse map: paraId → aligned-v1-paragraph (so v2-side redline
  // lookups against v1 also work).
  var v2ToV1Aligned = new Array(v2Paras.length).fill(null);
  v1Paras.forEach(function (p1, i1) {
    var p2 = v1ToV2Aligned[i1];
    if (p2) v2ToV1Aligned[p2.idx] = p1;
  });
  // Build paraId → aligned-paragraph lookups (paraId is what redlines
  // carry; map straight to the aligned counterpart paragraph).
  var v1AlignedV2ByParaId = {};
  v1Paras.forEach(function (p1, i1) {
    if (!p1.paraId) return;
    var p2 = v1ToV2Aligned[i1];
    if (p2) v1AlignedV2ByParaId[p1.paraId] = p2;
  });
  var v2AlignedV1ByParaId = {};
  v2Paras.forEach(function (p2, i2) {
    if (!p2.paraId) return;
    var p1 = v2ToV1Aligned[i2];
    if (p1) v2AlignedV1ByParaId[p2.paraId] = p1;
  });
  // 2026-05-17 v15: COUNT-BASED check. Substring "is text in v2 para?"
  // gives false positives when the redline text appears MULTIPLE TIMES
  // in the same paragraph (e.g. counterparty deletes one occurrence of
  // "disclosed by" in a paragraph that has two occurrences of "disclosed
  // by" — accepting the deletion still leaves one occurrence, but
  // substring check says "still there → rejected"). Count comparison
  // disambiguates: a deletion ACCEPTED drops the count by 1; REJECTED
  // keeps it the same. An insertion ACCEPTED raises the count by 1;
  // REJECTED keeps it the same.
  var _countOccurrences = function (haystack, needle) {
    if (!needle) return 0;
    var n = String(needle).toLowerCase().replace(/\s+/g, " ").trim();
    if (!n) return 0;
    var h = String(haystack).toLowerCase().replace(/\s+/g, " ").trim();
    var c = 0, i = 0;
    while ((i = h.indexOf(n, i)) !== -1) { c++; i += n.length; }
    return c;
  };
  // For a v1 INSERTION of `text` in paragraph p1:
  //   v1 acceptedText  (= post-insertion view) has count K
  //   v1 originalText  (= pre-insertion view)  has count K-1 (insertion stripped)
  //   v2 acceptedText  (current state):
  //     count == K   → accepted (the insertion stayed in)
  //     count == K-1 → rejected (the insertion was reverted)
  //   Use the COUNT, not substring — handles "the text already appears
  //   elsewhere in the paragraph" correctly.
  var _insertionAccepted = function (text, paraId) {
    var p2 = paraId ? v1AlignedV2ByParaId[paraId] : null;
    if (!p2) return false; // paragraph gone in v2 → insertion didn't survive
    var p1 = paraId ? v1ParaById[paraId] : null;
    if (!p1) return false;
    var v1AccCount = _countOccurrences(p1.acceptedText || "", text);
    var v2Count = _countOccurrences(p2.acceptedText || "", text);
    return v2Count >= v1AccCount; // count maintained or grew → insertion is in v2
  };
  // For a v1 DELETION of `text` in paragraph p1:
  //   v1 originalText (= pre-deletion view)  has count K
  //   v1 acceptedText (= post-deletion view) has count K-1 (deletion stripped)
  //   v2 acceptedText (current state):
  //     count == K-1 → accepted (deletion stayed applied — text gone)
  //     count == K   → rejected (deletion reverted — text put back)
  var _deletionAccepted = function (text, paraId) {
    var p2 = paraId ? v1AlignedV2ByParaId[paraId] : null;
    if (!p2) return true; // paragraph gone in v2 → text deleted along with paragraph
    var p1 = paraId ? v1ParaById[paraId] : null;
    if (!p1) return true;
    var v1AccCount = _countOccurrences(p1.acceptedText || "", text);
    var v2Count = _countOccurrences(p2.acceptedText || "", text);
    return v2Count <= v1AccCount; // count stayed at the "deletion applied" level
  };
