  // Used by the whole-paragraph unmarked-add detection downstream.
  var inV1Clean = function (text, paraId) {
    var n = normText(text);
    if (n.length < 2) return false;
    var alignedP1 = paraId ? v2AlignedV1ByParaId[paraId] : null;
