  Object.keys(v1InsSet).forEach(function (k) {
    var ins = v1InsSet[k];
    if (v2InsSet[k]) {
      transitions.push({
        type: "retained-pending-insertion", paragraphIdx: v2InsSet[k].paraIdx,
        paraId: ins.paraId, text: ins.text, author: ins.author, date: ins.date, source: "v1",
      });
      counts.retained++; return;
    }
    // Count-based check: did the insertion text's count in the
    // aligned v2 paragraph match the post-insertion count from v1?
    if (_insertionAccepted(ins.text, ins.paraId)) {
      transitions.push({
        type: "accepted-insertion", paragraphIdx: ins.paraIdx, paraId: ins.paraId,
        text: ins.text, author: ins.author, date: ins.date, source: "v1",
      });
      counts.accepted++;
    } else {
      transitions.push({
        type: "rejected-insertion", paragraphIdx: ins.paraIdx, paraId: ins.paraId,
        text: ins.text, author: ins.author, date: ins.date, source: "v1",
      });
      counts.rejected++;
