  // v1 deletions: retained-pending / rejected / accepted
  Object.keys(v1DelSet).forEach(function (k) {
    var del = v1DelSet[k];
    if (v2DelSet[k]) {
      transitions.push({
        type: "retained-pending-deletion", paragraphIdx: v2DelSet[k].paraIdx,
        paraId: del.paraId, text: del.text, author: del.author, date: del.date, source: "v1",
      });
      counts.retained++; return;
    }
    // Count-based check: a deletion is ACCEPTED when v2's count of
    // the text matches v1's post-deletion count; REJECTED when v2's
    // count is back to v1's pre-deletion count (text put back).
    if (_deletionAccepted(del.text, del.paraId)) {
      transitions.push({
        type: "accepted-deletion", paragraphIdx: del.paraIdx, paraId: del.paraId,
        text: del.text, author: del.author, date: del.date, source: "v1",
      });
      counts.accepted++;
    } else {
      transitions.push({
        type: "rejected-deletion", paragraphIdx: del.paraIdx, paraId: del.paraId,
        text: del.text, author: del.author, date: del.date, source: "v1",
      });
      counts.rejected++;
    }
  });
  // v2-only insertions/deletions: newly introduced
  Object.keys(v2InsSet).forEach(function (k) {
    if (v1InsSet[k]) return;
    var ins = v2InsSet[k];
    transitions.push({
      type: "new-insertion", paragraphIdx: ins.paraIdx, paraId: ins.paraId,
      text: ins.text, author: ins.author, date: ins.date, source: "v2",
    });
    counts.newRedlines++;
  });
  Object.keys(v2DelSet).forEach(function (k) {
    if (v1DelSet[k]) return;
    var del = v2DelSet[k];
    transitions.push({
      type: "new-deletion", paragraphIdx: del.paraIdx, paraId: del.paraId,
      text: del.text, author: del.author, date: del.date, source: "v2",
    });
    counts.newRedlines++;
  });
  // Whole-paragraph deletions (no redlines on a paragraph that vanished)
  v1Paras.forEach(function (p, v1i) {
    if (p.pendingIns.length || p.pendingDel.length) return;
    var clean = (p.acceptedText || "").trim();
    if (clean.length < 8) return;
    // Survival = paragraph had a paraId or content-similarity alignment
    // to some v2 paragraph. Computed earlier in v1ToV2Aligned. If null,
    // the paragraph was deleted wholesale → emit accepted-deletion.
    if (v1ToV2Aligned[v1i]) return;
    transitions.push({
      type: "accepted-deletion", paragraphIdx: v1i, paraId: p.paraId,
      text: clean, author: "", date: "", source: "v1",
    });
    counts.accepted++;
  });
  // Unmarked-change detection (counterparty edits without track changes)
  var v1ById = {};
  v1Paras.forEach(function (p) { if (p.paraId) v1ById[p.paraId] = p; });
  var wordDiff = function (aText, bText) {
    var a = String(aText || "").split(/\s+/).filter(Boolean);
    var b = String(bText || "").split(/\s+/).filter(Boolean);
    var m = a.length, n = b.length;
    if (m === 0 && n === 0) return { inserted: [], deleted: [] };
    var dp = new Array(m + 1);
    for (var i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1);
    for (var i2 = 1; i2 <= m; i2++) {
      for (var j = 1; j <= n; j++) {
        if (a[i2 - 1].toLowerCase() === b[j - 1].toLowerCase()) dp[i2][j] = dp[i2 - 1][j - 1] + 1;
        else dp[i2][j] = dp[i2 - 1][j] >= dp[i2][j - 1] ? dp[i2 - 1][j] : dp[i2][j - 1];
      }
    }
    var inserted = [], deleted = [];
    var ii = m, jj = n;
    while (ii > 0 && jj > 0) {
      if (a[ii - 1].toLowerCase() === b[jj - 1].toLowerCase()) { ii--; jj--; }
      else if (dp[ii - 1][jj] >= dp[ii][jj - 1]) { deleted.unshift(a[ii - 1]); ii--; }
      else { inserted.unshift(b[jj - 1]); jj--; }
    }
    while (ii > 0) { deleted.unshift(a[ii - 1]); ii--; }
    while (jj > 0) { inserted.unshift(b[jj - 1]); jj--; }
    return { inserted: inserted, deleted: deleted };
  };
  var multisetIntersect = function (xs, ys) {
    var bag = {};
    xs.forEach(function (w) { var k = w.toLowerCase(); bag[k] = (bag[k] || 0) + 1; });
    var out = [];
    ys.forEach(function (w) { var k = w.toLowerCase(); if (bag[k] > 0) { out.push(w); bag[k]--; } });
    return out;
  };
  // Inline unmarked changes
  v2Paras.forEach(function (v2p, v2i) {
    if (!v2p.paraId) return;
    var v1p = v1ById[v2p.paraId];
    if (!v1p) return;
    var v1A = v1p.acceptedText || "", v2A = v2p.acceptedText || "";
    var v1Ro = v1p.originalText || "", v2Ro = v2p.originalText || "";
    if (normText(v1A) === normText(v2A) && normText(v1Ro) === normText(v2Ro)) return;
    var accDiff = wordDiff(v1A, v2A);
    var rejDiff = wordDiff(v1Ro, v2Ro);
    var unmarkedIns = multisetIntersect(accDiff.inserted, rejDiff.inserted);
    var unmarkedDel = multisetIntersect(accDiff.deleted, rejDiff.deleted);
    if (unmarkedIns.length === 0 && unmarkedDel.length === 0) return;
    var insStr = unmarkedIns.join(" ").replace(/[^\w]/g, "");
    var delStr = unmarkedDel.join(" ").replace(/[^\w]/g, "");
    if (insStr.length + delStr.length < 3) return;
    transitions.push({
      type: "unmarked-change", paragraphIdx: v2i, paraId: v2p.paraId,
      text: (unmarkedIns.length ? "+\"" + unmarkedIns.join(" ") + "\"" : "") +
            (unmarkedIns.length && unmarkedDel.length ? "  " : "") +
            (unmarkedDel.length ? "−\"" + unmarkedDel.join(" ") + "\"" : ""),
      addedText: unmarkedIns.join(" "), removedText: unmarkedDel.join(" "),
      author: "(no track changes)", date: "", source: "v2",
    });
    counts.unmarked++;
  });
  // Whole-paragraph unmarked additions
  v2Paras.forEach(function (v2p, v2i) {
    if (!v2p.paraId) return;
    if (v1ById[v2p.paraId]) return;
    if (v2p.pendingIns.length || v2p.pendingDel.length) return;
    var clean = (v2p.acceptedText || "").trim();
    if (clean.length < 8) return;
    if (inV1Clean(clean)) return;
    transitions.push({
      type: "unmarked-change", paragraphIdx: v2i, paraId: v2p.paraId,
      text: "+\"" + (clean.length > 240 ? clean.slice(0, 240) + "…" : clean) + "\"  (entire paragraph added without track changes)",
      addedText: clean, removedText: "",
      author: "(no track changes)", date: "", source: "v2", wholeParagraph: true,
    });
    counts.unmarked++;
  });
  // Group fragmented Word redlines (single user edit split across
  // multiple <w:ins>/<w:del>). Joiner is " … " (NOT " "): Word splits
  // edits at run boundaries, so a "single" insertion can be 5 separate
  // OOXML elements. Joining with " " strips the plain text that
  // originally connected the fragments → produces gibberish that
  // looks like a quoted sentence but isn't ("either Party the
  // disclosing Party in good faith ..."). The ellipsis makes the
  // fragmentation visible to both the AI and the human reader, and
  // also flags the prompt to describe it as a paragraph-level edit
  // rather than quote it verbatim. Also tag the merged entry with a
  // fragment count so the AI can detect heavy fragmentation.
  var grouped = {};
  var orderedKeys = [];
  transitions.forEach(function (t) {
    var key = t.paragraphIdx + "|" + t.type + "|" + (t.author || "") + "|" + (t.date || "").slice(0, 10);
    if (!grouped[key]) {
      var copy = Object.assign({}, t);
      copy._fragmentCount = 1;
      grouped[key] = copy;
      orderedKeys.push(key);
    } else {
      var prev = grouped[key].text || "";
      var add = t.text || "";
      if (prev.toLowerCase().indexOf(add.toLowerCase()) === -1) {
        grouped[key].text = prev ? prev + " … " + add : add;
        grouped[key]._fragmentCount = (grouped[key]._fragmentCount || 1) + 1;
      }
    }
  });
  var mergedTransitions = orderedKeys.map(function (k) { return grouped[k]; });
  var mergedCounts = { accepted: 0, rejected: 0, newRedlines: 0, retained: 0, unmarked: 0 };
  mergedTransitions.forEach(function (t) {
    if (t.type === "accepted-insertion" || t.type === "accepted-deletion") mergedCounts.accepted++;
    else if (t.type === "rejected-insertion" || t.type === "rejected-deletion") mergedCounts.rejected++;
    else if (t.type === "new-insertion" || t.type === "new-deletion") mergedCounts.newRedlines++;
    else if (t.type.indexOf("retained-") === 0) mergedCounts.retained++;
    else if (t.type === "unmarked-change") mergedCounts.unmarked++;
  });
  return { transitions: mergedTransitions, summary: mergedCounts };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // 2026-06-03 — delegate to error_review's shared mascot loader.
  // error_review is preload-tier; dispatch always lands.
  var _cmpProgressCtrl = null;
  function _cmpShowSmile(message, onCancel) {
    // 2026-06-04: removed pre-emptive _cmpHideSmile() — dispatch reuses
    // existing mascot, no more fade-in flicker on re-calls.
    try {
      var v2L = document.getElementById("loading");
      if (v2L) v2L.classList.add("hidden");
      var kernelOv = document.getElementById("_eli3_loading_overlay");
      if (kernelOv && kernelOv.parentNode) kernelOv.parentNode.removeChild(kernelOv);
    } catch (e) {}
    try {
      _cmpProgressCtrl = eli.dispatch("error_review", "showProgress", {
        message: message || "Comparing documents…",
        onCancel: onCancel,
      });
    } catch (e) { _cmpProgressCtrl = null; }
  }
  function _cmpHideSmile() {
    if (_cmpProgressCtrl && typeof _cmpProgressCtrl.close === "function") {
      try { _cmpProgressCtrl.close(); } catch (_) {}
      _cmpProgressCtrl = null;
    } else {
      try { eli.dispatch("error_review", "hideProgress"); } catch (_) {}
    }
    try {
      var v2L = document.getElementById("loading");
      if (v2L) v2L.classList.add("hidden");
    } catch (e) {}
  }
  function _cmpPaintSmileLoader(onCancel) { _cmpShowSmile("Comparing documents…", onCancel); }
  // Exposed for runVersionCompare.js (separate file in the bundle —
  // closure-scoped helpers aren't visible across files post-eval).
  if (typeof window !== "undefined") {
    window._cmpPaintSmileLoader = _cmpPaintSmileLoader;
    window._cmpHideSmile = _cmpHideSmile;
  }

  // ─── v2 PROMPTS / getPrompt / formatPrompt — tool-owned ───────────
  // Compare is the primary consumer of PROMPTS.COMPARE (own
  // runVersionCompare + delegates to risk_rules_manager's
  // runDeal360Analysis). Boot-tier load order means these window
  // globals are available before any caller fires.
  //
  // PROMPTS.COMPARE template is INLINED verbatim from v2 (working
  // pre-audit snapshot). The earlier IDB-routed version silently
  // failed when the prompts data bundle wasn't installed in the
  // user's IDB — the AI got called with an empty prompt and the
  // compare overlay never rendered. Self-contained + zero IDB
  // dependency = identical to how v2 worked.
  if (!window._cmpPromptsInstalled) {
    window._cmpPromptsInstalled = true;
    var _promptCache = null;
    var _promptCacheLoading = null;
    function _loadCache() {
      if (_promptCache) return Promise.resolve(_promptCache);
      if (_promptCacheLoading) return _promptCacheLoading;
      if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve({});
      _promptCacheLoading = eli.storage.getAll("prompts").then(function (rows) {
        var map = {};
        (rows || []).forEach(function (r) {
          if (r && r.id && typeof r.text === "string") map[r.id] = r.text;
        });
        _promptCache = map;
        _promptCacheLoading = null;
        return map;
      }).catch(function () { _promptCacheLoading = null; return {}; });
      return _promptCacheLoading;
    }
    _loadCache();
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("data:installed", function (payload) {
        if (!payload || !payload.id || /prompts/i.test(payload.id)) _promptCache = null;
        _loadCache();
      });
    }
    if (typeof window.getPrompt !== "function") {
      window.getPrompt = function (key, fallback) {
        if (!_promptCache && !_promptCacheLoading) _loadCache();
        return (_promptCache || {})[key] || fallback || "";
      };
    }
    if (typeof window.formatPrompt !== "function") {
      window.formatPrompt = function (key, params, fallback) {
        var tpl = window.getPrompt(key, fallback);
        if (!tpl) return "";
        params = params || {};
        return tpl.replace(/\{\{(\w+)\}\}/g, function (_, name) {
          return params[name] != null ? String(params[name]) : "";
        });
      };
    }
    if (typeof window.PROMPTS !== "object" || !window.PROMPTS) window.PROMPTS = {};
    if (typeof window.PROMPTS.COMPARE !== "function") {
      // 2026-05-16: docB is now passed as a JSON-stringified anchored
      // array `[{id, text}, ...]` where id is "ELI_IDX_<n>". The AI
      // returns the id of the matching paragraph for each change, so
      // LOCATE can jump via highlightAnchor instead of body.search.
      // Deletions get id="" (no paragraph in docB to anchor to).
      window.PROMPTS.COMPARE = function (docA, docB, mode, poMode) {
        var labelA = mode === "template" ? "STANDARD TEMPLATE" : "OLD VERSION";
        var labelB = mode === "template" ? "DRAFT" : "NEW VERSION";
        var originInstructions;
        if (poMode === "3rd party") {
          originInstructions = "\n    >>> THIRD-PARTY PAPER MODE <<<\n    THIS DRAFT WAS NOT BASED ON OUR TEMPLATE. Do NOT do a literal word-for-word comparison because the boilerplate structures will inherently differ.\n    Instead, act as a semantic conceptual mapper by following these steps:\n    1. EXTRACT & MAP: First, mentally extract the core legal concepts from both documents. Map them conceptually (e.g. Draft Indemnity vs Template Indemnity) REGARDLESS of where they physically appear or how they are numbered in the text.\n    2. MICRO-COMPARE: Only compare the conceptually paired clauses. IGNORE stylings, structural ordering (e.g. moving a clause from Section 2 to 14), and boilerplate introductory wording.\n    3. ONLY REPORT MATERIAL DEVIATIONS IN LEGAL POSITION (e.g., Liability Caps, varying Cure Periods, missing Mutualities, different Warranty standards).\n    4. If the draft accomplishes the exact same legal intent as the template but uses different phrasing or is located in a different section, DO NOT REPORT THIS AS A CHANGE.\n    5. CRITICAL: If a material concept, protection, or right exists in the STANDARD TEMPLATE but fails to map to any semantic equivalent in the DRAFT, you MUST report it! Set 'new_snippet' to '[DELETED]'.\n    6. RECALL BIAS: When uncertain between \"same intent\" vs \"different legal effect\", prefer reporting as a change (Moderate unless clearly Critical/Minor) rather than suppressing.\n    7. COVERAGE CHECKLIST: Explicitly verify and report variance/missing coverage for: payment timing and milestones, liability cap amount/scope, indemnity scope and carve-outs, IP ownership/license terms, confidentiality term/survival, audit rights, data privacy/security obligations, termination triggers/cure windows, governing law/forum, assignment/subcontracting, warranties/disclaimers, insurance, and limitation carve-outs.\n    8. VOCABULARY: Do NOT use redlining terminology like \"Removal of\", \"Changed from\", or \"Modified\". This is a completely different document. Use auditing terminology: \"Draft omits...\", \"Draft deviates from standard by...\", or \"Draft takes alternate position on...\".";
        } else {
          originInstructions = "\n    >>> OUR PAPER MODE (STRICT REDLINE) <<<\n    This draft is based directly on the " + labelA + ". Run a strict, literal text diff with high recall.\n    Identify all removed phrases, altered limits, modified wording, qualifier changes (e.g., \"reasonable\", \"material\"), numeric/date changes, and scope narrowing/broadening.";
        }
        var returnFormat;
        if (poMode === "3rd party") {
          returnFormat = "\n    CRITICAL SCORING INSTRUCTION:\n    You must evaluate the holistic legal alignment of the Draft against the Standard Template and output a \"similarity_score\" (Integer 0-100). \n    DO NOT base this score purely on word-count or text overlap. You must weight the score based on LEGAL LEVERAGE and RISK POSTURE.\n    If the draft materially alters, guts, or omits critical risk-shifting clauses—specifically Intellectual Property Ownership, Limitation of Liability, Indemnification, or Termination rights—you MUST drastically lower the score (e.g., 20-50%), even if 90% of the standard boilerplate text remains unchanged. A highly restrictive or one-sided draft must never score above 60%.\n\n    RETURN RAW JSON OBJECT:\n    {\n       \"similarity_score\": 40,\n       \"similarity_text\": \"One sentence explaining the score.\",\n       \"critical_summary\": [\"Draft omits standard limitation of liability cap.\"],\n       \"overall_assessment\": \"One sentence summarizing the overall posture of this draft.\",\n       \"changes\": [{\"section\": \"Clause Name\", \"change_type\": \"Critical|Moderate|Minor\", \"description\": \"...\", \"legal_impact\": \"...\", \"id\": \"EXACT id from the docB JSON array (e.g. 'ELI_IDX_47') OR empty string for deletions\", \"original_snippet\": \"verbatim from docA or '[NEWLY ADDED]'\", \"new_snippet\": \"verbatim from docB or '[DELETED]'\"}]\n    }";
        } else {
          returnFormat = "RETURN RAW JSON OBJECT:\n    {\n       \"critical_summary\": [\"Counterparty deleted the 30-day cure period.\"],\n       \"overall_assessment\": \"One sentence summary.\",\n       \"changes\": [{\"section\": \"Clause Name\", \"change_type\": \"Critical|Moderate|Minor\", \"description\": \"...\", \"legal_impact\": \"...\", \"id\": \"EXACT id from the docB JSON array (e.g. 'ELI_IDX_47') OR empty string for deletions\", \"original_snippet\": \"verbatim from docA or '[NEWLY ADDED]'\", \"new_snippet\": \"verbatim from docB or '[DELETED]'\"}]\n    }";
        }
        // Pass docB as anchored JSON when caller supplied one (now the
        // standard for fresh scans). Wrap a notice so the AI knows the
        // input shape and that ids in returned changes MUST come from
        // this JSON. When docB is plain text (legacy callers, version
        // diffs without indexing), use the raw fallback.
        var docBNotice;
        var docBBlock;
        if (typeof docB === "string" && docB.length > 1 && docB.charAt(0) === "[") {
          // Heuristic: looks like a JSON array.
          docBNotice = "\n    >>> docB IS PROVIDED AS AN INDEXED JSON ARRAY <<<\n    Each entry is shaped { \"id\": \"ELI_IDX_<n>\", \"text\": \"<paragraph text>\" }. For every change you identify, set the change's `id` field to the EXACT id of the docB paragraph where the change lives. For deletions (text in docA missing from docB), set id to empty string \"\".";
          docBBlock = String(docB).substring(0, 1500000);
        } else {
          docBNotice = "";
          docBBlock = String(docB || "").substring(0, 1000000);
        }
        return "You are a Senior Legal Editor for Colgate-Palmolive and where relevant its subsidiary Hill's Pet Nutrition.\n    TASK: Compare \"" + labelA + "\" against \"" + labelB + "\" and report changes.\n    " + originInstructions + docBNotice + "\n    STRICT REPORTING RULES:\n    1. NO HALLUCINATIONS: Only report a change if you can find the exact text in the source.\n    2. HEADING PROTECTION: Do NOT report Section Headings as Added if only the body changed.\n    3. STATE LABELS: missing → new_snippet=[DELETED]; addition → original_snippet=[NEWLY ADDED]; modification → full verbatim text.\n    4. VERBATIM SNIPPETS ONLY: snippet fields must be exact substrings.\n    5. COMPREHENSIVE EXTRACTION: be exhaustive across all substantive legal provisions.\n    6. GROUPING: one delta per changes entry.\n    7. IGNORE renumbering / whitespace / fonts.\n    8. PLACEHOLDER FILLS: docA (the template) MAY contain bracketed placeholders like `[Liability Cap Amount]`, `[Party Name]`, `[Effective Date]`, `[Notice Period]`, `[Governing Law]`, `[$ Amount]`, etc. These are intentional fill-in slots. If the ONLY difference between docA and docB at a given clause is that docB has filled the placeholder with a concrete value (e.g. docA: \"$[Liability Cap Amount]\" → docB: \"$5,000,000\"), DO NOT report it as a change. ONLY report if the substantive legal position differs (e.g. docA: \"liability capped at $[X]\" → docB: \"liability capped at $5M PLUS attorney fees\" — the additional clause IS a substantive change worth reporting).\n    " + returnFormat + "\n    --- " + labelA + " ---\n    " + String(docA || "").substring(0, 1000000) + "\n    --- " + labelB + " ---\n    " + docBBlock;
      };
    }
  }

  // The compare tool's functions are top-level in their v2 files — the
  // bundler exposes them via window.* on eval. Capture refs once so we
  // can wire them through eli.register without re-checking each call.
  var showCompareToTemplateApp = window.showCompareToTemplateApp;
  var runVersionCompare        = window.runVersionCompare;
  var showTemplateSelectionOverlay = window.showTemplateSelectionOverlay;
  if (!showCompareToTemplateApp) {
    eli.log.event("tool", "compare_load_failed", { fns: Object.keys(window).filter(function (k) { return /^show|^run|^compare/i.test(k); }) });
    return;
  }

  // ─── Tile handler ────────────────────────────────────────────────
  // Click the Compare tile → launch the picker (template / upload /
  // past version). Records stat for usage tracking + leaves an activity
  // entry so the user can restore later.
  function _launch() {
    // 2026-05-18 v48: stat MOVED to tile-only wrapper below. _launch is
    // also called by compare:launch (fired by legal_review), and three
    // activity_restore handlers — counting them all inflated the tally.
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); }
    catch (e) {}
    try { showCompareToTemplateApp(); }
    catch (e) {
      eli.log.event("tool", "compare_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Compare failed to open: " + (e.message || "unknown"), "err");
    }
  }

  // Called by legal_risks when the launcher set a comparePayload.
  // Split into fetch+render so legal_risks can kick the AI off in
  // PARALLEL with its own scan (v2-faithful Promise.all timing). v2:
  // both AI calls fired in parallel, then both renders happened after
  // legal_risks's render painted the target div. Same shape here.
  function _resolveBaseline(payload) {
    if (!payload) return "";
    if (payload.template) {
      // 2026-05-24: indexed templates may carry content as plain text +
      // envelope (JSON {body, customXmlParts}). Compare wants plain text.
      // Prefer .content (kept up-to-date by showCompareSettings save-back);
      // fall back to body OOXML text-extraction if only .envelope exists.
      var t = payload.template;
      if (t.content) return t.content;
      if (t.envelope) {
        try {
          var env = JSON.parse(t.envelope);
          if (env && typeof env.body === "string") {
            return env.body.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
          }
        } catch (_e) {}
      }
      return "";
    }
    if (payload.version) {
      if (payload.version.html) return String(payload.version.html).replace(/<[^>]+>/g, " ");
      return payload.version.text || "";
    }
    return payload.text || "";
  }
  function _fetchCompareData(opts) {
    if (!opts || !opts.payload) return Promise.resolve(null);
    var baseline = _resolveBaseline(opts.payload);
    if (!baseline) return Promise.resolve(null);
    var mode = opts.mode || "new";
    var poMode = (mode === "template" || mode === "new") ? "3rd party" : "our";
    // 2026-05-16: pre-index docB (the current doc) via getPromptAnchors
    // — writes ELI_IDX_* bookmarks AND returns the [{id, text}] shape
    // the prompt now expects. AI returns id for each change so LOCATE
    // can jump via highlightAnchor (Tier 0) instead of body.search.
    // Falls back to plain text if the helper is unavailable.
    var helpers = eli.host && eli.host.helpers;
    var docBP = (helpers && typeof helpers.getPromptAnchors === "function")
      ? helpers.getPromptAnchors({ minLen: 5 }).then(function (anchors) {
          return JSON.stringify(anchors || []);
        }).catch(function () {
          return eli.host.readText({}).then(function (t) { return String(t || ""); });
        })
      : eli.host.readText({}).then(function (t) { return String(t || ""); });
    return docBP.then(function (docB) {
      var prompt = window.PROMPTS.COMPARE(baseline, docB, mode, poMode);
      return eli.ai.completeJSON(prompt);
    }).catch(function (err) {
      eli.log.event("tool", "compare_run_fetch_failed", { msg: err && err.message });
      return null;
    });
  }
  function _renderCompareData(data, mode, targetId) {
    if (!data) return;
    targetId = targetId || "_eli3_lr_compare_target";
    if (typeof window.renderCompareResults !== "function") return;
    try { window.renderCompareResults(data, mode || "new", targetId); }
    catch (err) { eli.log.event("tool", "compare_run_render_failed", { msg: err && err.message }); }
    // 2026-05-13: activity entry on COMPARE COMPLETE — replaces the
    // open-time picker entry. Restore fires `compare.runIntoCard` so
    // the cards re-render with the same data, in the same scoped mount.
    try {
      if (eli.activity && eli.activity.add) {
        var changes = (data && data.changes) || [];
        var crit = 0, mod = 0, minor = 0;
        changes.forEach(function (c) {
          var t = String((c && c.change_type) || (c && c.impact) || "").toLowerCase();
          if (t.indexOf("crit") !== -1 || t.indexOf("high") !== -1) crit++;
          else if (t.indexOf("mod") !== -1 || t.indexOf("med") !== -1) mod++;
          else if (t.indexOf("minor") !== -1 || t.indexOf("low") !== -1) minor++;
        });
        var parts = [];
        if (crit) parts.push(crit + " Critical");
        if (mod)  parts.push(mod + " Moderate");
        if (minor) parts.push(minor + " Minor");
        var summary;
        if (data && typeof data.similarity_score === "number") {
          summary = data.similarity_score + "% match" + (parts.length ? " · " + parts.join(" · ") : "");
        } else if (changes.length) {
