  // 2026-05-13 composite refactor: scoped-mount entry. legal_review's
  // composite landing dispatches `compare.runIntoCard({targetId, payload,
  // mode})` which kicks the compare AI, renders into the named card
  // body, AND resolves with a header-friendly summary so the parent can
  // populate the card header. Shape:
  //   { summary, criticalCount, moderateCount, minorCount, total,
  //     similarityScore, similarityText }
  //
  // 2026-05-13 follow-up: every silent-null exit path in _fetchCompareData
  // gets a visible error state in the target card body + a rejected
  // Promise so the parent shows "⚠ <reason>" in the header. Previously
  // these would leave the spinner spinning forever.
  function _renderErrorIntoCard(targetId, label, msg) {
    var el = (targetId && document.getElementById(targetId));
    if (el) {
      el.innerHTML =
        '<div style="padding:28px 22px;margin:8px;border:1px solid #fecaca;background:#fef2f2;">' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:.5px;text-transform:uppercase;color:#b91c1c;">⚠ ' + label + '</div>' +
          '<div style="margin-top:8px;font:500 12px/1.5 Inter,sans-serif;color:#7f1d1d;">' +
            String(msg || "").replace(/[<>&]/g, "") +
          '</div>' +
        '</div>';
    }
  }
  function _runIntoCard(opts) {
    opts = opts || {};
    if (!opts.targetId) return Promise.reject(new Error("targetId required"));
    // Diagnostic — surfaces in event log so we can see how the call landed.
    eli.log.event("tool", "compare_runIntoCard_start", {
      targetId: opts.targetId,
      mode: opts.mode || "new",
      hasPayload: !!opts.payload,
      payloadKeys: opts.payload ? Object.keys(opts.payload) : null,
      hasTemplate: !!(opts.payload && opts.payload.template),
      templateContentLen: opts.payload && opts.payload.template && String(opts.payload.template.content || "").length,
    });
    // Validate inputs before kicking the AI.
    if (!opts.payload) {
      _renderErrorIntoCard(opts.targetId, "No payload",
        "compare.runIntoCard was called without a comparePayload. Legal Review couldn't pick a template — open the Compare tile to pick one manually.");
      return Promise.reject(new Error("no payload"));
    }
    var baselineProbe = _resolveBaseline(opts.payload);
    if (!baselineProbe) {
      _renderErrorIntoCard(opts.targetId, "Empty baseline",
        "The matched template has no content. Check that the template body was saved correctly via Template Studio.");
      return Promise.reject(new Error("empty baseline"));
    }
    if (!window.eli.ai || !window.eli.ai.hasApiKey || !window.eli.ai.hasApiKey()) {
      _renderErrorIntoCard(opts.targetId, "No API key",
        "Set a Gemini API key in Settings → Global before running Compare.");
      return Promise.reject(new Error("no api key"));
    }
    return _fetchCompareData(opts).then(function (data) {
      if (!data) {
        _renderErrorIntoCard(opts.targetId, "AI returned nothing",
          "The compare AI call resolved but produced no parsable JSON. Check the event log for compare_run_fetch_failed entries.");
        throw new Error("AI returned no data");
      }
      // 2026-05-13 follow-up: renderCompareResults uses appendChild,
      // so it adds cards on TOP of whatever's already in the target
      // (the composite spinner). Clear the target first so the result
      // replaces the pending state instead of stacking under it.
      var _targetEl = document.getElementById(opts.targetId);
      if (_targetEl) _targetEl.innerHTML = "";
      _renderCompareData(data, opts.mode, opts.targetId);
      // Build summary from the result shape (compare's AI returns
      // {summary, similarity_score, similarity_text, critical_summary,
      // changes:[{change_type:'Critical|Moderate|Minor', ...}]} for
      // 3rd-party mode, OR {summary, changes:[...]} for our-paper).
      var changes = (data && data.changes) || [];
      var crit = 0, mod = 0, minor = 0;
      changes.forEach(function (c) {
        var t = String((c && c.change_type) || c.impact || "").toLowerCase();
        if (t.indexOf("crit") !== -1 || t.indexOf("high") !== -1) crit++;
        else if (t.indexOf("mod") !== -1 || t.indexOf("med") !== -1) mod++;
        else if (t.indexOf("minor") !== -1 || t.indexOf("low") !== -1) minor++;
      });
      var parts = [];
      if (crit) parts.push(crit + " Critical");
      if (mod)  parts.push(mod + " Moderate");
      if (minor) parts.push(minor + " Minor");
      var summary;
      if (data && typeof data.similarity_score === "number") {
        summary = data.similarity_score + "% match" + (parts.length ? " · " + parts.join(" · ") : "");
      } else if (changes.length) {
        summary = changes.length + " change" + (changes.length === 1 ? "" : "s") +
          (parts.length ? " · " + parts.join(" · ") : "");
      } else {
        summary = "No material changes";
      }
      return {
        summary: summary,
        criticalCount: crit, moderateCount: mod, minorCount: minor,
        total: changes.length,
        similarityScore: (typeof data.similarity_score === "number") ? data.similarity_score : null,
        similarityText: data && data.similarity_text || data && data.overall_assessment || null,
      };
    }).catch(function (err) {
      // Last-line safety: an unexpected throw in the render path also
      // gets surfaced into the card body so the spinner doesn't hang.
      var msg = (err && err.message) || String(err || "");
      _renderErrorIntoCard(opts.targetId, "Compare failed", msg);
      eli.log.event("tool", "compare_runIntoCard_failed", { msg: msg.slice(0, 200) });
      throw err;
    });
  }

