          var revisions = body.getTrackedChanges();
          revisions.load("items");
          return context.sync().then(function () {
            if (!revisions.items || !revisions.items.length) return null;
            var cands = [];
            for (var i = 0; i < revisions.items.length; i++) {
              var rev = revisions.items[i];
              rev.load("type");
              var rr = rev.getRange();
              rr.load("text");
              var ox = rr.getOoxml();
              cands.push({ change: rev, range: rr, ooxml: ox });
            }
            return context.sync().then(function () {
              var hintNorm = _cmpNorm(options.deletedSnippet);
              var clauseNorm = _cmpNorm(clauseRef);
              var best = null, bestScore = -1;
              for (var j = 0; j < cands.length; j++) {
                var c = cands[j];
                var t = String(c.change.type || "").toLowerCase();
                if (options.isDeletion) {
                  if (t !== "deletion" && t !== "deleted") continue;
                } else if (t !== "deletion" && t !== "deleted" &&
                           t !== "replacement" && t !== "insertion") {
                  continue;
                }
                var cText = c.range.text || _cmpExtractTextFromOoxml(c.ooxml.value) || "";
                var cNorm = _cmpNorm(cText);
                if (!cNorm) continue;
                var score = 0;
                if (hintNorm) {
                  if (cNorm === hintNorm) score += 100;
                  else if (cNorm.indexOf(hintNorm) !== -1 || hintNorm.indexOf(cNorm) !== -1) score += 75;
                  var hintWords = hintNorm.split(/\s+/).filter(function (w) { return w.length > 3; });
                  for (var hw = 0; hw < hintWords.length; hw++) {
                    if (cNorm.indexOf(hintWords[hw]) !== -1) score += 5;
                  }
                }
                if (clauseNorm && cNorm.indexOf(clauseNorm) !== -1) score += 20;
                if (score > bestScore) { bestScore = score; best = c; }
              }
              if (best && bestScore > 0) {
                try { best.range.select(); } catch (e) {}
                try { best.range.scrollIntoView(); } catch (e) {}
                return _checkSameSection(best.range).then(function (isSame) {
                  return context.sync().then(function () {
                    return { type: "FOUND_TRACKED", count: 1, isSameSection: isSame };
                  });
                });
              }
              return null;
            });
          });
        }

        // Body-search anchor cascade — v3 replacement for v2's
        // EliLocate + fastLocateClause path. Builds multiple candidate
        // anchors (full clean text, snippets, mid/head/tail slices,
        // clauseRef) and tries each via body.search with the same
        // forgiving options v2 used (ignoreSpace + ignorePunctuation).
        function _bodySearchCascade() {
          var anchorsRaw = [
            clean,
            options.originalSnippet || "",
            options.newSnippet || "",
            options.deletedSnippet || "",
          ];
          if (clean.length > 20) {
            var words = clean.split(/\s+/);
            if (words.length > 6) {
              var mid = Math.floor(words.length / 2);
              anchorsRaw.push(words.slice(mid, mid + 5).join(" "));
              anchorsRaw.push(words.slice(-5).join(" "));
              anchorsRaw.push(words.slice(0, 5).join(" "));
            }
          }
          anchorsRaw.push(clauseRef || "");
          // 2026-05-13: build TWO variants per anchor — the raw form +
          // a glyph-normalized form (smart quotes / em-dashes / NBSP /
          // ellipsis / soft hyphens stripped). Doc may have either; AI
          // returns either; we don't know which. Search both shapes so
          // either match wins.
          var seen = {};
          var anchors = [];
          function _addAnchor(s) {
            var anc = String(s || "")
              .replace(/\[DELETED\]|\[NEWLY ADDED\]/gi, "")
              .replace(/[\r\n\t]+/g, " ").trim();
            if (anc.length > 120) anc = anc.substring(0, 120).trim();
            if (anc.length < 4) return;
            var k = anc.toLowerCase();
            if (seen[k]) return;
            seen[k] = true;
            anchors.push(anc);
          }
          for (var a = 0; a < anchorsRaw.length; a++) {
            _addAnchor(anchorsRaw[a]);
            var alt = _cmpGlyphNorm(anchorsRaw[a]);
            if (alt && alt !== anchorsRaw[a]) _addAnchor(alt);
          }
          function _tryAnchor(i) {
            if (i >= anchors.length) return Promise.resolve(null);
            var sr = body.search(anchors[i], {
              matchCase: false, ignorePunct: true, ignoreSpace: true,
            });
            sr.load("items");
            return context.sync().then(function () {
              if (sr.items && sr.items.length) {
                var tgt = sr.items[0];
                try { tgt.select(); } catch (e) {}
                try { tgt.scrollIntoView(); } catch (e) {}
                return _checkSameSection(tgt).then(function (isSame) {
                  return context.sync().then(function () {
                    return { type: "FOUND", count: sr.items.length, isSameSection: isSame };
                  });
                });
              }
              return _tryAnchor(i + 1);
            });
          }
          return _tryAnchor(0);
        }

        return _trackedChangeBranch().then(function (tc) {
          if (tc) return tc;
          return _bodySearchCascade().then(function (bs) {
            if (bs) return bs;
            return { type: "NONE" };
          });
        });
      }).then(function (res) {
        if (!res || res.type === "NONE") {
          if (typeof showToast === "function") showToast("⚠️ Could not locate.", "warn");
          return;
        }
        if (res.isSameSection) {
          if (typeof showToast === "function") showToast("ℹ️ Already in the same section", "info");
          return;
        }
        var label = clauseRef ? " (" + clauseRef + ")" : "";
        if (res.count && res.count > 1) {
          if (typeof showToast === "function") showToast("📍 Located" + label + " (multiple matches)", "ok");
        } else {
          if (typeof showToast === "function") showToast("📍 Located" + label, "ok");
        }
      }).catch(function (err) {
        try { eli.log.event("tool", "compare_locate_failed", { msg: err && err.message }); } catch (_) {}
        if (typeof showToast === "function") showToast("⚠️ Could not locate.", "warn");
      });
    };
  }

  // v2 `_tpStripOoxmlNoise(xml)` — strips rsid/date noise from OOXML
  // so OOXML diff isn't drowned in formatting artifacts. Compare's
  // runVersionCompare calls this when it has both snapshots.
  //
  // 2026-05-17: aligned with v2 (taskpane_v2.js:8846). Was missing
  // w:id / w:date / w16du:dateUtc / w14:textId strips, and was using
  // `\s+` prefix where v2 used single `\s`. Both differences caused
  // the current doc's OOXML normalization to mismatch the stored
  // snapshot's bodyOoxml, breaking redline-aware compare's text
  // matching. Aligning here so current and historical use identical
  // cleanup.
  if (typeof window._tpStripOoxmlNoise !== "function") {
    window._tpStripOoxmlNoise = function (xml) {
      if (!xml || typeof xml !== "string") return xml || "";
      return xml
        .replace(/\sw:id="[^"]*"/g, "")
        .replace(/\sw:date="[^"]*"/g, "")
        .replace(/\sw16du:dateUtc="[^"]*"/g, "")
        .replace(/\sw14:textId="[^"]*"/g, "")
        .replace(/\sw:rsid[A-Za-z]*="[^"]*"/g, "");
    };
  }

  // Expose the ported snapshot-redline functions as globals so the v2
  // tools (runVersionCompare.js) find them under the same names they
  // used in v2. The functions themselves live in snapshotsRedlineAware.js
  // (loaded via tool_configs.files) and run pure over OOXML strings.
  if (typeof compareSnapshotsRedlineAware === "function" &&
      typeof window.compareSnapshotsRedlineAware !== "function") {
    window.compareSnapshotsRedlineAware = compareSnapshotsRedlineAware;
  }
  if (typeof _eliExtractParagraphRedlineSpans === "function" &&
      typeof window._eliExtractParagraphRedlineSpans !== "function") {
    window._eliExtractParagraphRedlineSpans = _eliExtractParagraphRedlineSpans;
  }

  // checkRedlinesBeforeScan shim removed 2026-05-12 — risk_rules_manager
  // now owns its own redline gate (_rrmRedlineGate) and reads via
  // eli.host.hasRedlines(). compare itself doesn't call it.

  // 2026-05-16: v2-compat window.getLegalTextWithAnchors shim DELETED.
  // No live caller in v3 (only doc-comment references remain in
  // risk_rules_manager). The kernel function it wrapped
  // (eli.host.readTextWithAnchors) is also deleted in this same
  // refactor — every tool migrated to eli.host.helpers.getPromptAnchors
  // which writes shared ELI_IDX_* bookmarks.

  // v2 `checkQuirkyTrophy(name, payload)` — re-routed to v3 trophies
  // channel. Tools that fire quirky-trophy events can keep using the
  // v2 name without knowing the kernel split.
  if (typeof window.checkQuirkyTrophy !== "function") {
    window.checkQuirkyTrophy = function (name, payload) {
      try {
        if (eli.dispatch) {
          eli.dispatch("trophies", "unlocked", {
            id: String(name || "quirky"),
            icon: "🏆",
            title: String(name || "Achievement"),
            desc: "",
            quirkyPayload: payload || null,
          });
        }
      } catch (e) { /* tolerate */ }
    };
  }

  // getPrompt / formatPrompt / PROMPTS now live in the kernel — single
  // source of truth (taskpane_v3.js, after the callGemini shim). Kept
  // here as a pointer so the next dev doesn't re-add a per-tool copy.

  // v2 `askUserSelectionScope()` — popped a dialog asking the user
  // whether to scan the SELECTION or the WHOLE document when they had
  // text selected. v3 version_history / risk_rules_manager call this.
  // Default to "fullDoc" so the scan runs without an extra interrupt.
  if (typeof window.askUserSelectionScope !== "function") {
    window.askUserSelectionScope = function () {
      // Tiny premium picker. Resolves "selection" or "fullDoc".
      if (typeof showEliDialog !== "function") return Promise.resolve("fullDoc");
      return new Promise(function (resolve, reject) {
        showEliDialog({
          variant: "info", icon: "📐",
          title: "Scan scope",
          body:
            '<div style="font:500 12px/1.5 \'Inter\',sans-serif;color:#475569;">' +
              'You have text selected. Scan just the selection or the whole document?' +
            '</div>',
          primary: { label: "Whole document", onclick: function () { resolve("fullDoc"); } },
          secondary: { label: "Just selection", onclick: function () { resolve("selection"); } },
          onClose: function () { reject(new Error("Cancelled")); },
        });
      });
    };
  }

  // v2 `handleFileSelect(file, cb)` — reads a .docx/.pdf file and calls
  // back with extracted text. compare uses this for the "upload file"
  // comparison source. Kernel doesn't expose this; for v3 we use the
  // ask_eli reader if loaded, else a minimal text-only fallback.
  if (typeof window.handleFileSelect !== "function") {
    window.handleFileSelect = function (file, cb) {
      var reader = new FileReader();
      reader.onload = function () {
        var content = reader.result;
        // .txt: decode bytes directly.
        if (typeof content === "string") return cb(content);
        // .docx/.pdf: needs mammoth/pdf.js. If not available, hand the
        // file off to the AI as a binary attachment (compare's downstream
        // legal_risks engine handles binary input via eli.ai.complete).
        try {
          var bytes = new Uint8Array(content);
          var sample = Array.prototype.slice.call(bytes.slice(0, 4))
            .map(function (b) { return String.fromCharCode(b); }).join("");
          // .docx starts with "PK" (zip header), .pdf with "%PDF".
          if (sample.indexOf("%PDF") === 0 && typeof window.pdfjsLib !== "undefined") {
            // pdf.js path (kernel may load it on demand).
            cb("[PDF text extraction requires pdf.js — paste the text manually]");
            return;
          }
          if (sample.indexOf("PK") === 0 && typeof window.mammoth !== "undefined") {
            window.mammoth.extractRawText({ arrayBuffer: content }).then(function (res) {
              cb(res && res.value ? res.value : "");
            }).catch(function () { cb(""); });
            return;
          }
          // No extractor available — best we can do is pass empty + warn.
          if (typeof showToast === "function") {
            showToast("File reader unavailable for " + (file.name || "this format"), "warn");
          }
          cb("");
        } catch (e) {
          cb("");
        }
      };
      reader.onerror = function () { cb(""); };
      // .docx + .pdf → arrayBuffer, .txt → text.
      var name = String(file.name || "").toLowerCase();
      if (name.endsWith(".txt")) reader.readAsText(file);
      else reader.readAsArrayBuffer(file);
    };
  }

  // ─── Activity entry on compare launch ────────────────────────────
  // 2026-05-13 follow-up: dropped the open-time picker entry. It was a
  // payloadless "Opened Compare picker" record whose restore just re-
  // opened the picker — no value as a session bookmark. The meaningful
  // entry is added on COMPARE COMPLETE (renderCompareResults) which now
  // carries the full result + a restoreFn that re-renders the cards.
  // Same pattern as review_redlines / final_review / legal_risks fixes.

  eli.log.event("tool", "compare_initialized", {});
}
